    mod verify_cert {

        use core::fmt;
        use core::ops::ControlFlow;
        #[cfg(all())]
        use std::vec::Vec;

        #[cfg(all())]
        use crate::android_debug_bridge::pki_types::SubjectPublicKeyInfoDer;
        use crate::android_debug_bridge::pki_types::{
            CertificateDer, SignatureVerificationAlgorithm, TrustAnchor, UnixTime,
        };

        use crate::android_debug_bridge::webpki::cert::Cert;
        use crate::android_debug_bridge::webpki::crl::RevocationOptions;
        use crate::android_debug_bridge::webpki::der::{self, FromDer};
        use crate::android_debug_bridge::webpki::end_entity::EndEntityCert;
        use crate::android_debug_bridge::webpki::error::Error;
        #[cfg(all())]
        use crate::android_debug_bridge::webpki::spki_for_anchor;
        use crate::android_debug_bridge::webpki::{public_values_eq, subject_name};

        pub(in crate::android_debug_bridge::webpki) struct ChainOptions<'a, 'p> {
            pub(in crate::android_debug_bridge::webpki) eku: &'a dyn ExtendedKeyUsageValidator,
            pub(in crate::android_debug_bridge::webpki) supported_sig_algs:
                &'a [&'a dyn SignatureVerificationAlgorithm],
            pub(in crate::android_debug_bridge::webpki) trust_anchors: &'p [TrustAnchor<'p>],
            pub(in crate::android_debug_bridge::webpki) intermediate_certs:
                &'p [CertificateDer<'p>],
            pub(in crate::android_debug_bridge::webpki) revocation: Option<RevocationOptions<'a>>,
        }

        impl<'a, 'p: 'a> ChainOptions<'a, 'p> {
            #[allow(clippy::type_complexity)]
            pub(in crate::android_debug_bridge::webpki) fn build_chain(
                &self,
                end_entity: &'p EndEntityCert<'p>,
                time: UnixTime,
                verify_path: Option<&dyn Fn(&VerifiedPath<'_>) -> Result<(), Error>>,
            ) -> Result<VerifiedPath<'p>, Error> {
                let mut path = PartialPath::new(end_entity);
                match self.build_chain_inner(
                    &mut path,
                    time,
                    verify_path,
                    0,
                    &mut Budget::default(),
                ) {
                    Ok(anchor) => Ok(VerifiedPath::new(end_entity, anchor, path)),
                    Err(ControlFlow::Break(err)) | Err(ControlFlow::Continue(err)) => Err(err),
                }
            }

            #[allow(clippy::type_complexity)]
            fn build_chain_inner(
                &self,
                path: &mut PartialPath<'p>,
                time: UnixTime,
                verify_path: Option<&dyn Fn(&VerifiedPath<'_>) -> Result<(), Error>>,
                sub_ca_count: usize,
                budget: &mut Budget,
            ) -> Result<&'p TrustAnchor<'p>, ControlFlow<Error, Error>> {
                let role = path.node().role();

                check_issuer_independent_properties(
                    path.head(),
                    time,
                    role,
                    sub_ca_count,
                    self.eku,
                )?;

                let result = loop_while_non_fatal_error(
                    Error::UnknownIssuer,
                    self.trust_anchors,
                    |trust_anchor| {
                        let trust_anchor_subject =
                            crate::android_debug_bridge::untrusted::Input::from(
                                trust_anchor.subject.as_ref(),
                            );
                        if !public_values_eq(path.head().issuer, trust_anchor_subject) {
                            return Err(Error::UnknownIssuer.into());
                        }

                        let node = path.node();
                        self.check_signed_chain(&node, time, trust_anchor, budget)?;
                        check_signed_chain_name_constraints(&node, trust_anchor, budget)?;

                        let Some(verify) = verify_path else {
                            return Ok(trust_anchor);
                        };

                        let candidate = VerifiedPath {
                            end_entity: path.end_entity,
                            intermediates: Intermediates::Borrowed(
                                &path.intermediates[..path.used],
                            ),
                            anchor: trust_anchor,
                        };

                        match verify(&candidate) {
                            Ok(()) => Ok(trust_anchor),
                            Err(err) => Err(ControlFlow::Continue(err)),
                        }
                    },
                );

                let err = match result {
                    Ok(anchor) => return Ok(anchor),

                    res @ Err(ControlFlow::Break(_)) => return res,

                    Err(ControlFlow::Continue(err)) => err,
                };

                loop_while_non_fatal_error(err, self.intermediate_certs, |cert_der| {
                    let potential_issuer = Cert::from_der(
                        crate::android_debug_bridge::untrusted::Input::from(cert_der),
                    )?;
                    if !public_values_eq(potential_issuer.subject, path.head().issuer) {
                        return Err(Error::UnknownIssuer.into());
                    }

                    if path.node().iter().any(|prev| {
                        public_values_eq(potential_issuer.spki, prev.cert.spki)
                            && public_values_eq(potential_issuer.subject, prev.cert.subject)
                    }) {
                        return Err(Error::UnknownIssuer.into());
                    }

                    let next_sub_ca_count = match role {
                        Role::EndEntity => sub_ca_count,
                        Role::Issuer => sub_ca_count + 1,
                    };

                    budget.consume_build_chain_call()?;
                    path.push(potential_issuer)?;
                    let result =
                        self.build_chain_inner(path, time, verify_path, next_sub_ca_count, budget);
                    if result.is_err() {
                        path.pop();
                    }

                    result
                })
            }

            fn check_signed_chain(
                &self,
                path: &PathNode<'_>,
                time: UnixTime,
                trust_anchor: &TrustAnchor<'_>,
                budget: &mut Budget,
            ) -> Result<(), ControlFlow<Error, Error>> {
                let mut spki_value = crate::android_debug_bridge::untrusted::Input::from(
                    trust_anchor.subject_public_key_info.as_ref(),
                );
                let mut issuer_subject = crate::android_debug_bridge::untrusted::Input::from(
                    trust_anchor.subject.as_ref(),
                );
                let mut issuer_key_usage = None;
                for path in path.iter() {
                    path.cert
                        .signed_data
                        .verify(self.supported_sig_algs, spki_value, budget)?;

                    if let Some(revocation_opts) = &self.revocation {
                        revocation_opts.check(
                            &path,
                            issuer_subject,
                            spki_value,
                            issuer_key_usage,
                            self.supported_sig_algs,
                            budget,
                            time,
                        )?;
                    }

                    spki_value = path.cert.spki;
                    issuer_subject = path.cert.subject;
                    issuer_key_usage = path.cert.key_usage;
                }

                Ok(())
            }
        }

        pub struct VerifiedPath<'p> {
            end_entity: &'p EndEntityCert<'p>,
            intermediates: Intermediates<'p>,
            anchor: &'p TrustAnchor<'p>,
        }

        impl<'p> VerifiedPath<'p> {
            fn new(
                end_entity: &'p EndEntityCert<'p>,
                anchor: &'p TrustAnchor<'p>,
                partial: PartialPath<'p>,
            ) -> Self {
                Self {
                    end_entity,
                    intermediates: Intermediates::Owned {
                        certs: partial.intermediates,
                        used: partial.used,
                    },
                    anchor,
                }
            }

            pub fn intermediate_certificates(&'p self) -> IntermediateIterator<'p> {
                IntermediateIterator {
                    intermediates: self.intermediates.as_ref(),
                }
            }

            pub fn end_entity(&self) -> &'p EndEntityCert<'p> {
                self.end_entity
            }

            pub fn anchor(&self) -> &'p TrustAnchor<'p> {
                self.anchor
            }

            #[cfg(all())]
            pub fn issuer_spki(&self) -> SubjectPublicKeyInfoDer<'p> {
                match self.intermediate_certificates().next() {
                    Some(issuer) => issuer.subject_public_key_info(),
                    None => spki_for_anchor(self.anchor),
                }
            }
        }

        pub struct IntermediateIterator<'a> {
            intermediates: &'a [Option<Cert<'a>>],
        }

        impl<'a> Iterator for IntermediateIterator<'a> {
            type Item = &'a Cert<'a>;

            fn next(&mut self) -> Option<Self::Item> {
                match self.intermediates.split_first() {
                    Some((head, tail)) => {
                        self.intermediates = tail;
                        Some(head.as_ref().unwrap())
                    }
                    None => None,
                }
            }
        }

        impl DoubleEndedIterator for IntermediateIterator<'_> {
            fn next_back(&mut self) -> Option<Self::Item> {
                match self.intermediates.split_last() {
                    Some((head, tail)) => {
                        self.intermediates = tail;
                        Some(head.as_ref().unwrap())
                    }
                    None => None,
                }
            }
        }

        #[allow(clippy::large_enum_variant)]
        enum Intermediates<'a> {
            Owned {
                certs: [Option<Cert<'a>>; MAX_SUB_CA_COUNT],
                used: usize,
            },
            Borrowed(&'a [Option<Cert<'a>>]),
        }

        impl<'a> AsRef<[Option<Cert<'a>>]> for Intermediates<'a> {
            fn as_ref(&self) -> &[Option<Cert<'a>>] {
                match self {
                    Intermediates::Owned { certs, used } => &certs[..*used],
                    Intermediates::Borrowed(certs) => certs,
                }
            }
        }

        fn check_signed_chain_name_constraints(
            path: &PathNode<'_>,
            trust_anchor: &TrustAnchor<'_>,
            budget: &mut Budget,
        ) -> Result<(), ControlFlow<Error, Error>> {
            let mut name_constraints = trust_anchor
                .name_constraints
                .as_ref()
                .map(|der| crate::android_debug_bridge::untrusted::Input::from(der.as_ref()));

            for path in path.iter() {
                crate::android_debug_bridge::untrusted::read_all_optional(
                    name_constraints,
                    Error::BadDer,
                    |value| subject_name::check_name_constraints(value, &path, budget),
                )?;

                name_constraints = path.cert.name_constraints;
            }

            Ok(())
        }

        pub(in crate::android_debug_bridge::webpki) struct Budget {
            signatures: usize,
            build_chain_calls: usize,
            name_constraint_comparisons: usize,
        }

        impl Budget {
            #[inline]
            pub(in crate::android_debug_bridge::webpki) fn consume_signature(
                &mut self,
            ) -> Result<(), Error> {
                self.signatures = self
                    .signatures
                    .checked_sub(1)
                    .ok_or(Error::MaximumSignatureChecksExceeded)?;
                Ok(())
            }

            #[inline]
            fn consume_build_chain_call(&mut self) -> Result<(), Error> {
                self.build_chain_calls = self
                    .build_chain_calls
                    .checked_sub(1)
                    .ok_or(Error::MaximumPathBuildCallsExceeded)?;
                Ok(())
            }

            #[inline]
            pub(in crate::android_debug_bridge::webpki) fn consume_name_constraint_comparison(
                &mut self,
            ) -> Result<(), Error> {
                self.name_constraint_comparisons = self
                    .name_constraint_comparisons
                    .checked_sub(1)
                    .ok_or(Error::MaximumNameConstraintComparisonsExceeded)?;
                Ok(())
            }
        }

        impl Default for Budget {
            fn default() -> Self {
                Self {
                    signatures: 100,

                    build_chain_calls: 200_000,

                    name_constraint_comparisons: 250_000,
                }
            }
        }

        fn check_issuer_independent_properties(
            cert: &Cert<'_>,
            time: UnixTime,
            role: Role,
            sub_ca_count: usize,
            eku: &dyn ExtendedKeyUsageValidator,
        ) -> Result<(), Error> {
            cert.validity
                .read_all(Error::BadDer, |value| check_validity(value, time))?;
            crate::android_debug_bridge::untrusted::read_all_optional(
                cert.basic_constraints,
                Error::BadDer,
                |value| check_basic_constraints(value, role, sub_ca_count),
            )?;
            crate::android_debug_bridge::untrusted::read_all_optional(
                cert.eku,
                Error::BadDer,
                |input| check_eku(input, eku),
            )?;

            Ok(())
        }

        fn check_eku(
            input: Option<&mut crate::android_debug_bridge::untrusted::Reader<'_>>,
            eku: &dyn ExtendedKeyUsageValidator,
        ) -> Result<(), Error> {
            match input {
                Some(input) if input.at_end() => Err(Error::EmptyEkuExtension),
                Some(input) => eku.validate(KeyPurposeIdIter { input }),
                None => eku.validate(KeyPurposeIdIter {
                    input: &mut crate::android_debug_bridge::untrusted::Reader::new(
                        crate::android_debug_bridge::untrusted::Input::from(&[]),
                    ),
                }),
            }
        }

        fn check_validity(
            input: &mut crate::android_debug_bridge::untrusted::Reader<'_>,
            time: UnixTime,
        ) -> Result<(), Error> {
            let not_before = UnixTime::from_der(input)?;
            let not_after = UnixTime::from_der(input)?;

            if not_before > not_after {
                return Err(Error::InvalidCertValidity);
            }
            if time < not_before {
                return Err(Error::CertNotValidYet { time, not_before });
            }
            if time > not_after {
                return Err(Error::CertExpired { time, not_after });
            }

            Ok(())
        }

        fn check_basic_constraints(
            input: Option<&mut crate::android_debug_bridge::untrusted::Reader<'_>>,
            role: Role,
            sub_ca_count: usize,
        ) -> Result<(), Error> {
            let (is_ca, path_len_constraint) = match input {
                Some(input) => {
                    let is_ca = bool::from_der(input)?;

                    let path_len_constraint = if !input.at_end() {
                        Some(usize::from(u8::from_der(input)?))
                    } else {
                        None
                    };

                    (is_ca, path_len_constraint)
                }
                None => (false, None),
            };

            match (role, is_ca, path_len_constraint) {
                (Role::EndEntity, true, _) => Err(Error::CaUsedAsEndEntity),
                (Role::Issuer, false, _) => Err(Error::EndEntityUsedAsCa),
                (Role::Issuer, true, Some(len)) if sub_ca_count > len => {
                    Err(Error::PathLenConstraintViolated)
                }
                _ => Ok(()),
            }
        }

        #[derive(Clone, PartialEq, Eq)]
        pub struct RequiredEkuNotFoundContext {
            #[cfg(all())]
            pub required: ExtendedKeyUsage,

            #[cfg(all())]
            pub present: Vec<Vec<usize>>,
        }

        impl fmt::Debug for RequiredEkuNotFoundContext {
            fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
                let mut builder = f.debug_struct("RequiredEkuNotFoundContext");
                #[cfg(all())]
                builder.field(
                    "required",
                    match &self.required.inner {
                        EkuValidationMode::Required(inner) => inner,
                        EkuValidationMode::RequiredIfPresent(inner) => inner,
                    },
                );
                #[cfg(all())]
                builder.field("present", &EkuListDebug(&self.present));
                builder.finish()
            }
        }

        #[cfg(all())]
        struct EkuListDebug<'a>(&'a [Vec<usize>]);

        #[cfg(all())]
        impl fmt::Debug for EkuListDebug<'_> {
            fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
                write!(f, "[")?;
                for (i, part) in self.0.iter().enumerate() {
                    if i > 0 {
                        write!(f, ", ")?;
                    }

                    write!(f, "KeyPurposeId(")?;
                    for (j, part) in part.iter().enumerate() {
                        if j > 0 {
                            write!(f, ".")?;
                        }
                        write!(f, "{part}")?;
                    }
                    write!(f, ")")?;
                }
                write!(f, "]")
            }
        }

        #[derive(Clone, Copy, Debug, Eq, PartialEq)]
        pub struct ExtendedKeyUsage {
            inner: EkuValidationMode,
        }

        impl ExtendedKeyUsage {
            pub const fn server_auth() -> Self {
                Self::required_if_present(EKU_SERVER_AUTH)
            }

            pub const fn client_auth() -> Self {
                Self::required_if_present(EKU_CLIENT_AUTH)
            }

            pub const fn required(oid: &'static [u8]) -> Self {
                Self {
                    inner: EkuValidationMode::Required(KeyPurposeId::new(oid)),
                }
            }

            pub const fn required_if_present(oid: &'static [u8]) -> Self {
                Self {
                    inner: EkuValidationMode::RequiredIfPresent(KeyPurposeId::new(oid)),
                }
            }

            pub fn oid_values(&self) -> impl Iterator<Item = usize> + '_ {
                OidDecoder::new(
                    match &self.inner {
                        EkuValidationMode::Required(eku) => eku,
                        EkuValidationMode::RequiredIfPresent(eku) => eku,
                    }
                    .oid_value
                    .as_slice_less_safe(),
                )
            }

            pub const SERVER_AUTH_REPR: &[usize] = &[1, 3, 6, 1, 5, 5, 7, 3, 1];

            pub const CLIENT_AUTH_REPR: &[usize] = &[1, 3, 6, 1, 5, 5, 7, 3, 2];
        }

        impl ExtendedKeyUsageValidator for ExtendedKeyUsage {
            fn validate(&self, iter: KeyPurposeIdIter<'_, '_>) -> Result<(), Error> {
                let mut empty = true;
                #[cfg(all())]
                let mut present = Vec::new();

                for id in iter {
                    empty = false;
                    let id = id?;
                    if self.inner.id() == id {
                        return Ok(());
                    }

                    #[cfg(all())]
                    present.push(id.to_decoded_oid());
                }

                match (empty, self.inner) {
                    (true, EkuValidationMode::RequiredIfPresent(_)) => Ok(()),
                    _ => Err(Error::RequiredEkuNotFound(RequiredEkuNotFoundContext {
                        #[cfg(all())]
                        required: Self { inner: self.inner },
                        #[cfg(all())]
                        present,
                    })),
                }
            }
        }

        pub trait ExtendedKeyUsageValidator {
            fn validate(&self, iter: KeyPurposeIdIter<'_, '_>) -> Result<(), Error>;
        }

        #[derive(Clone, Copy, Debug, Eq, PartialEq)]
        enum EkuValidationMode {
            Required(KeyPurposeId<'static>),

            RequiredIfPresent(KeyPurposeId<'static>),
        }

        impl EkuValidationMode {
            fn id(&self) -> KeyPurposeId<'static> {
                match self {
                    Self::Required(id) => *id,
                    Self::RequiredIfPresent(id) => *id,
                }
            }
        }

        pub struct KeyPurposeIdIter<'a, 'r> {
            input: &'r mut crate::android_debug_bridge::untrusted::Reader<'a>,
        }

        impl<'a, 'r> Iterator for KeyPurposeIdIter<'a, 'r> {
            type Item = Result<KeyPurposeId<'a>, Error>;

            fn next(&mut self) -> Option<Self::Item> {
                if self.input.at_end() {
                    return None;
                }

                Some(
                    der::expect_tag(self.input, der::Tag::OID)
                        .map(|oid_value| KeyPurposeId { oid_value }),
                )
            }
        }

        impl Drop for KeyPurposeIdIter<'_, '_> {
            fn drop(&mut self) {
                self.input.skip_to_end();
            }
        }

        #[derive(Clone, Copy)]
        pub struct KeyPurposeId<'a> {
            oid_value: crate::android_debug_bridge::untrusted::Input<'a>,
        }

        impl<'a> KeyPurposeId<'a> {
            pub const fn new(oid: &'a [u8]) -> Self {
                Self {
                    oid_value: crate::android_debug_bridge::untrusted::Input::from(oid),
                }
            }

            #[cfg(all())]
            pub fn to_decoded_oid(&self) -> Vec<usize> {
                OidDecoder::new(self.oid_value.as_slice_less_safe()).collect()
            }
        }

        impl fmt::Debug for KeyPurposeId<'_> {
            fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
                write!(f, "KeyPurposeId(")?;
                let decoder = OidDecoder::new(self.oid_value.as_slice_less_safe());
                for (i, part) in decoder.enumerate() {
                    if i > 0 {
                        write!(f, ".")?;
                    }
                    write!(f, "{part}")?;
                }
                write!(f, ")")
            }
        }

        impl PartialEq<Self> for KeyPurposeId<'_> {
            fn eq(&self, other: &Self) -> bool {
                public_values_eq(self.oid_value, other.oid_value)
            }
        }

        impl Eq for KeyPurposeId<'_> {}

        const EKU_SERVER_AUTH: &[u8] = &oid!(1, 3, 6, 1, 5, 5, 7, 3, 1);

        const EKU_CLIENT_AUTH: &[u8] = &oid!(1, 3, 6, 1, 5, 5, 7, 3, 2);

        pub(in crate::android_debug_bridge::webpki) struct OidDecoder<'a> {
            encoded: &'a [u8],
            left: Option<usize>,
            first: bool,
        }

        impl<'a> OidDecoder<'a> {
            pub(in crate::android_debug_bridge::webpki) fn new(encoded: &'a [u8]) -> Self {
                Self {
                    encoded,
                    left: None,
                    first: true,
                }
            }
        }

        impl Iterator for OidDecoder<'_> {
            type Item = usize;

            fn next(&mut self) -> Option<Self::Item> {
                if let Some(next) = self.left.take() {
                    return Some(next);
                }

                let mut cur = 0;
                for (i, &byte) in self.encoded.iter().enumerate() {
                    cur = (cur << 7) + usize::from(byte & 0x7f);
                    if byte & 0x80 > 0 {
                        continue;
                    }

                    if !self.first {
                        self.encoded = &self.encoded[i + 1..];
                        return Some(cur);
                    }

                    let (cur, next) = match cur {
                        ..=39 => (0, cur),
                        40..=79 => (1, cur - 40),
                        _ => (2, cur - 80),
                    };

                    self.encoded = &self.encoded[i + 1..];
                    self.first = false;
                    self.left = Some(next);
                    return Some(cur);
                }

                None
            }
        }

        fn loop_while_non_fatal_error<'a, V: IntoIterator + 'a>(
            default_error: Error,
            values: V,
            mut f: impl FnMut(V::Item) -> Result<&'a TrustAnchor<'a>, ControlFlow<Error, Error>>,
        ) -> Result<&'a TrustAnchor<'a>, ControlFlow<Error, Error>> {
            let mut error = default_error;
            for v in values {
                match f(v) {
                    Ok(anchor) => return Ok(anchor),

                    res @ Err(ControlFlow::Break(_)) => return res,

                    Err(ControlFlow::Continue(new_error)) => error = error.most_specific(new_error),
                }
            }
            Err(error.into())
        }

        pub(in crate::android_debug_bridge::webpki) struct PartialPath<'a> {
            end_entity: &'a EndEntityCert<'a>,

            intermediates: [Option<Cert<'a>>; MAX_SUB_CA_COUNT],

            used: usize,
        }

        impl<'a> PartialPath<'a> {
            pub(in crate::android_debug_bridge::webpki) fn new(
                end_entity: &'a EndEntityCert<'a>,
            ) -> Self {
                Self {
                    end_entity,
                    intermediates: Default::default(),
                    used: 0,
                }
            }

            pub(in crate::android_debug_bridge::webpki) fn push(
                &mut self,
                cert: Cert<'a>,
            ) -> Result<(), ControlFlow<Error, Error>> {
                if self.used >= MAX_SUB_CA_COUNT {
                    return Err(Error::MaximumPathDepthExceeded.into());
                }

                self.intermediates[self.used] = Some(cert);
                self.used += 1;
                Ok(())
            }

            fn pop(&mut self) {
                debug_assert!(self.used > 0);
                if self.used == 0 {
                    return;
                }

                self.used -= 1;
                self.intermediates[self.used] = None;
            }

            pub(in crate::android_debug_bridge::webpki) fn node(&self) -> PathNode<'_> {
                PathNode {
                    path: self,
                    index: self.used,
                    cert: self.head(),
                }
            }

            pub(in crate::android_debug_bridge::webpki) fn head(&self) -> &Cert<'a> {
                self.get(self.used)
            }

            fn get(&self, idx: usize) -> &Cert<'a> {
                match idx {
                    0 => self.end_entity,
                    _ => self.intermediates[idx - 1].as_ref().unwrap(),
                }
            }
        }

        const MAX_SUB_CA_COUNT: usize = 6;

        pub(in crate::android_debug_bridge::webpki) struct PathNode<'a> {
            path: &'a PartialPath<'a>,

            index: usize,

            pub(in crate::android_debug_bridge::webpki) cert: &'a Cert<'a>,
        }

        impl<'a> PathNode<'a> {
            pub(in crate::android_debug_bridge::webpki) fn iter(&self) -> PathIter<'a> {
                PathIter {
                    path: self.path,
                    next: Some(self.index),
                }
            }

            pub(in crate::android_debug_bridge::webpki) fn role(&self) -> Role {
                match self.index {
                    0 => Role::EndEntity,
                    _ => Role::Issuer,
                }
            }
        }

        pub(in crate::android_debug_bridge::webpki) struct PathIter<'a> {
            path: &'a PartialPath<'a>,
            next: Option<usize>,
        }

        impl<'a> Iterator for PathIter<'a> {
            type Item = PathNode<'a>;

            fn next(&mut self) -> Option<Self::Item> {
                let next = self.next?;
                self.next = match next {
                    0 => None,
                    _ => Some(next - 1),
                };

                Some(PathNode {
                    path: self.path,
                    index: next,
                    cert: self.path.get(next),
                })
            }
        }

        #[derive(Clone, Copy, PartialEq)]
        pub(in crate::android_debug_bridge::webpki) enum Role {
            Issuer,
            EndEntity,
        }
    }
