        struct Guard<'a> {
            state: &'a AtomicU8,
            new_state: u8,
        }

        impl<'a> Drop for Guard<'a> {
            fn drop(&mut self) {
                self.state.store(self.new_state, Ordering::Release);
                unsafe {
                    let key = self.state as *const AtomicU8 as usize;
                    parking_lot_core::unpark_all(key, parking_lot_core::DEFAULT_UNPARK_TOKEN);
                }
            }
        }

        #[inline(never)]
        fn initialize_inner(state: &AtomicU8, init: &mut dyn FnMut() -> bool) {
            loop {
                let exchange = state.compare_exchange_weak(
                    INCOMPLETE,
                    RUNNING,
                    Ordering::Acquire,
                    Ordering::Acquire,
                );
                match exchange {
                    Ok(_) => {
                        let mut guard = Guard {
                            state,
                            new_state: INCOMPLETE,
                        };
                        if init() {
                            guard.new_state = COMPLETE;
                        }
                        return;
                    }
                    Err(COMPLETE) => return,
                    Err(RUNNING) => unsafe {
                        let key = state as *const AtomicU8 as usize;
                        parking_lot_core::park(
                            key,
                            || state.load(Ordering::Relaxed) == RUNNING,
                            || (),
                            |_, _| (),
                            parking_lot_core::DEFAULT_PARK_TOKEN,
                            None,
                        );
                    },
                    Err(INCOMPLETE) => (),
                    Err(_) => debug_assert!(false),
                }
            }
        }
