    pub mod log {
        use crate::android_debug_bridge::tracing_core::field::{Field, ValueSet, Visit};
        use core::fmt;
        pub use log::*;

        pub(in crate::android_debug_bridge::tracing) struct LogValueSet<'a> {
            pub(in crate::android_debug_bridge::tracing) values: &'a ValueSet<'a>,
            pub(in crate::android_debug_bridge::tracing) is_first: bool,
        }

        impl<'a> fmt::Display for LogValueSet<'a> {
            #[inline]
            fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
                struct LogVisitor<'a, 'b> {
                    f: &'a mut fmt::Formatter<'b>,
                    is_first: bool,
                    result: fmt::Result,
                }

                impl Visit for LogVisitor<'_, '_> {
                    fn record_debug(&mut self, field: &Field, value: &dyn fmt::Debug) {
                        let res = if self.is_first {
                            self.is_first = false;
                            if field.name() == "message" {
                                write!(self.f, "{:?}", value)
                            } else {
                                write!(self.f, "{}={:?}", field.name(), value)
                            }
                        } else {
                            write!(self.f, " {}={:?}", field.name(), value)
                        };
                        if let Err(err) = res {
                            self.result = self.result.and(Err(err));
                        }
                    }

                    fn record_str(&mut self, field: &Field, value: &str) {
                        if field.name() == "message" {
                            self.record_debug(field, &format_args!("{}", value))
                        } else {
                            self.record_debug(field, &value)
                        }
                    }
                }

                let mut visit = LogVisitor {
                    f,
                    is_first: self.is_first,
                    result: Ok(()),
                };
                self.values.record(&mut visit);
                visit.result
            }
        }
    }

