                        quarter!(z1, z5, z9, zd);
                        quarter!(z2, z6, za, ze);
                        quarter!(z3, z7, zb, zf);
                        quarter!(z0, z5, za, zf);
                        quarter!(z1, z6, zb, zc);
                        quarter!(z2, z7, z8, zd);
