            pub(super) mod ct_copy {

                use core::hint::black_box;

                pub(in crate::android_debug_bridge::graviola) fn ct_copy<const N: usize>(
                    cond: bool,
                    output: &mut [u8; N],
                    if_false: &[u8; N],
                ) {
                    let mask = ((-(black_box(cond as i16))) >> 8) as u8;
                    for (out, ff) in output.iter_mut().zip(if_false.iter()) {
                        *out = *ff ^ (mask & (*out ^ *ff));
                    }
                }

                pub(in crate::android_debug_bridge::graviola) fn ct_select_i16(
                    bit: u8,
                    if_set: i16,
                    if_unset: i16,
                ) -> i16 {
                    let mask = ((-(black_box(bit as i32))) >> 16) as u16;
                    let if_set = if_set as u16;
                    let if_unset = if_unset as u16;
                    (if_unset ^ (mask & (if_set ^ if_unset))) as i16
                }
            }
            pub(super) mod ct_equal {

                use crate::android_debug_bridge::graviola::low::ct_compare_bytes;

                pub(in crate::android_debug_bridge::graviola) fn ct_equal(
                    a: &[u8],
                    b: &[u8],
                ) -> bool {
                    if a.len() != b.len() {
                        return false;
                    }

                    let diff = unsafe { ct_compare_bytes(a.as_ptr(), b.as_ptr(), a.len()) };
                    diff == 0
                }
            }

