        pub(in crate::android_debug_bridge::graviola::low) fn zero_bytes(ptr: *mut u8, len: usize) {

            unsafe { _zero_bytes(ptr, len) }
        }

        #[target_feature(enable = "avx,avx2")]
        unsafe fn _zero_bytes(ptr: *mut u8, len: usize) {

            unsafe {
                core::arch::asm!(
                    "       vpxor   {zero}, {zero}, {zero}",

                    "   2:  cmp {len}, 32",
                    "       jl  3f",
                    "       vmovdqu [{ptr}], {zero}",
                    "       add {ptr}, 32",
                    "       sub {len}, 32",
                    "       jmp 2b",

                    "   3:  sub {len}, 1",
                    "       jl  4f",
                    "       mov byte ptr [{ptr}], 0",
                    "       add {ptr}, 1",
                    "       jmp 3b",
                    "   4:  ",

                    ptr = inout(reg) ptr => _,
                    len = inout(reg) len => _,

                    zero = out(ymm_reg) _,
                )
            }
        }

        pub(in crate::android_debug_bridge::graviola::low) unsafe fn ct_compare_bytes(a: *const u8, b: *const u8, len: usize) -> u8 {
            let mut acc = 0u8;

            unsafe {
                core::arch::asm!(
                    "   2: cmp {len}, 0",
                    "      je  3f",
                    "      mov {tmp}, [{a}]",
                    "      xor {tmp}, [{b}]",
                    "      or  {acc}, {tmp}",
                    "      add {a}, 1",
                    "      add {b}, 1",
                    "      sub {len}, 1",
                    "      jmp 2b",
                    "   3:  ",
                    a = inout(reg) a => _,
                    b = inout(reg) b => _,
                    len = inout(reg) len => _,
                    tmp = inout(reg_byte) 0u8 => _,
                    acc = inout(reg_byte) acc,
                );
            }
            acc
        }

