        pub(in crate::android_debug_bridge::graviola) fn enter_cpu_state() -> u32 {
            dit::maybe_enable()
        }

        pub(in crate::android_debug_bridge::graviola) fn leave_cpu_state(old: u32) {
            dit::maybe_disable(old);

            unsafe { zero_neon_registers() }
        }

        #[target_feature(enable = "neon")]
