        pub(in crate::android_debug_bridge::graviola::low) fn zero_bytes(ptr: *mut u8, len: usize) {

            unsafe {
                core::arch::asm!(
                    "       eor {zero}.16b, {zero}.16b, {zero}.16b",

                    "   2:  cmp {len}, #16",
                    "       blt 3f",
                    "       st1 {{{zero}.16b}}, [{ptr}]",
                    "       add {ptr}, {ptr}, #16",
                    "       sub {len}, {len}, #16",
                    "       b 2b",

                    "   3:  subs {len}, {len}, #1",
                    "       blt 4f",
                    "       strb wzr, [{ptr}], #1",
                    "       b 3b",
                    "   4:  ",

                    ptr = inout(reg) ptr => _,
                    len = inout(reg) len => _,

                    zero = out(vreg) _,
                )
            }
        }

        pub(in crate::android_debug_bridge::graviola::low) unsafe fn ct_compare_bytes(a: *const u8, b: *const u8, len: usize) -> u8 {

            unsafe {
                let mut acc = 0u8;
                core::arch::asm!(
                    "   2: cmp  {len}, 0",
                    "      beq  3f",
                    "      ldrb {tmpa:w}, [{a}]",
                    "      ldrb {tmpb:w}, [{b}]",
                    "      eor  {tmpa:w}, {tmpa:w}, {tmpb:w}",
                    "      orr  {acc:w}, {acc:w}, {tmpa:w}",
                    "      add  {a}, {a}, 1",
                    "      add  {b}, {b}, 1",
                    "      sub  {len}, {len}, 1",
                    "      b    2b",
                    "   3:  ",
                    a = inout(reg) a => _,
                    b = inout(reg) b => _,
                    len = inout(reg) len => _,
                    tmpa = inout(reg) 0u8 => _,
                    tmpb = inout(reg) 0u8 => _,
                    acc = inout(reg) acc,
                );
                acc
            }
        }

        macro_rules! have_cpu_feature {
            ("neon") => {
                crate::android_debug_bridge::graviola::low::aarch64::cpu::test_toggle(
                    "neon",
                    std::arch::is_aarch64_feature_detected!("neon"),
                )
            };
            ("aes") => {
                crate::android_debug_bridge::graviola::low::aarch64::cpu::test_toggle("aes", std::arch::is_aarch64_feature_detected!("aes"))
            };
            ("pmull") => {
                crate::android_debug_bridge::graviola::low::aarch64::cpu::test_toggle(
                    "pmull",
                    std::arch::is_aarch64_feature_detected!("pmull"),
                )
            };
            ("sha2") => {
                crate::android_debug_bridge::graviola::low::aarch64::cpu::test_toggle(
                    "sha2",
                    std::arch::is_aarch64_feature_detected!("sha2"),
                )
            };
            ("sha3") => {
                crate::android_debug_bridge::graviola::low::aarch64::cpu::test_toggle(
                    "sha3",
                    std::arch::is_aarch64_feature_detected!("sha3"),
                )
            };
            ("dit") => {
                crate::android_debug_bridge::graviola::low::aarch64::cpu::test_toggle("dit", std::arch::is_aarch64_feature_detected!("dit"))
            };
        }

        #[derive(Clone, Copy, Debug)]
        pub(in crate::android_debug_bridge::graviola) struct HaveSha3(());

        impl HaveSha3 {
            pub(in crate::android_debug_bridge::graviola) fn check() -> Option<Self> {
                match have_cpu_feature!("sha3") {
                    true => Some(Self(())),
                    false => None,
                }
            }
        }

        pub(in crate::android_debug_bridge::graviola) fn verify_cpu_features() {
            assert!(
                have_cpu_feature!("neon"),
                "graviola requires neon CPU support"
            );
            assert!(
                have_cpu_feature!("aes"),
                "graviola requires aes CPU support"
            );
            assert!(
                have_cpu_feature!("pmull"),
                "graviola requires pmull CPU support"
            );
            assert!(
                have_cpu_feature!("sha2"),
                "graviola requires sha2 CPU support"
            );
        }

        mod dit {
            pub(super) fn maybe_enable() -> u32 {
                if have_cpu_feature!("dit") {

                    match unsafe { read() } {
                        0 => {

                            unsafe {
                                write(1);
                            };
                            1
                        }
                        _ => 0,
                    }
                } else {
                    0
                }
            }

            pub(super) fn maybe_disable(we_enabled: u32) {
                if we_enabled > 0 {

                    unsafe { write(0) }
                }
            }

            #[target_feature(enable = "dit")]
            fn read() -> u32 {
                let mut out: u64;

                unsafe {
                    core::arch::asm!(
                        "mrs {r}, DIT",
                        r = out(reg) out,
                    );
                }

                const DIT: u64 = 0x01000000;
                (out & DIT == DIT) as u32
            }

            #[target_feature(enable = "dit")]
            fn write(on: u32) {
                if on > 0 {

                    unsafe { core::arch::asm!("msr DIT, #1") }
                } else {

                    unsafe { core::arch::asm!("msr DIT, #0") }
                }
            }
        }

        #[cfg(not(debug_assertions))]
        pub(in crate::android_debug_bridge::graviola) fn test_toggle(_id: &str, detected: bool) -> bool {
            detected
        }

        #[cfg(debug_assertions)]
        pub(in crate::android_debug_bridge::graviola) fn test_toggle(id: &str, detected: bool) -> bool {
            if std::env::var(format!("GRAVIOLA_CPU_DISABLE_{id}")).is_ok() {
                println!("DEBUG: denying cpuid {id:?}");
                false
            } else {
                detected
            }
        }

        pub(in crate::android_debug_bridge::graviola::low) fn prefetch_ro<T>(ptr: *const T) {

            unsafe {
                core::arch::asm!(
                    "prfm pldl1strm, [{ptr}]",
                    ptr = in(reg) ptr,
                    options(readonly, nostack)
                );
            }
        }

        pub(in crate::android_debug_bridge::graviola::low) fn prefetch_rw<T>(ptr: *const T) {

            unsafe {
                core::arch::asm!(
                    "prfm pstl1keep, [{ptr}]",
                    ptr = in(reg) ptr,
                    options(readonly, nostack)
                );
            }
        }

