        pub(super) mod rsa_pub {

            use crate::android_debug_bridge::graviola::error::Error;
            use crate::android_debug_bridge::graviola::low;

            #[derive(Clone, Debug)]
            pub(in crate::android_debug_bridge::graviola) struct RsaPublicKey {
                pub(in crate::android_debug_bridge::graviola) n: RsaPosInt,
                pub(in crate::android_debug_bridge::graviola) e: u32,

                montifier: RsaPosInt,
                one: RsaPosInt,
                n0: u64,
            }

            impl RsaPublicKey {
                pub(in crate::android_debug_bridge::graviola) fn new(
                    n: RsaPosInt,
                    e: u32,
                ) -> Result<Self, Error> {
                    let n_len = n.len_bytes();
                    if n.is_even()
                        || !(MIN_PUBLIC_MODULUS_BYTES..=MAX_PUBLIC_MODULUS_BYTES).contains(&n_len)
                        || e == 0
                    {
                        return Err(Error::OutOfRange);
                    }

                    let montifier = n.montifier();

                    let n0 = n.mont_neg_inverse();

                    let one = n.fixed_one().mont_mul(&montifier, &n, n0);

                    Ok(Self {
                        n,
                        e,
                        montifier,
                        one,
                        n0,
                    })
                }

                pub(in crate::android_debug_bridge::graviola) fn modulus_len_bytes(&self) -> usize {
                    self.n.len_bytes()
                }

                pub(in crate::android_debug_bridge::graviola) fn public_op(
                    &self,
                    mut c: RsaPosInt,
                ) -> Result<RsaPosInt, Error> {
                    if !c.less_than(&self.n) {
                        return Err(Error::OutOfRange);
                    }
                    c.expand(&self.n);

                    let c_mont = c.to_montgomery(&self.montifier, &self.n);

                    let mut accum = self.one.clone();

                    let mut first = true;
                    for bit in (0..self.e.ilog2() + 1).rev() {
                        let tmp = if first {
                            first = false;
                            accum
                        } else {
                            accum.mont_sqr(&self.n, self.n0)
                        };

                        let mask = 1 << bit;
                        if self.e & mask == mask {
                            accum = tmp.mont_mul(&c_mont, &self.n, self.n0);
                        } else {
                            accum = tmp;
                        }
                    }

                    Ok(accum.from_montgomery(&self.n))
                }
            }

            const MAX_PUBLIC_MODULUS_BITS: usize = 8192;
            const MAX_PUBLIC_MODULUS_WORDS: usize = MAX_PUBLIC_MODULUS_BITS / 64;
            pub(in crate::android_debug_bridge::graviola) const MAX_PUBLIC_MODULUS_BYTES: usize =
                MAX_PUBLIC_MODULUS_BITS / 8;

            const MIN_PUBLIC_MODULUS_BITS: usize = 2048;
            const MIN_PUBLIC_MODULUS_BYTES: usize = MIN_PUBLIC_MODULUS_BITS / 8;

            type RsaPosInt = low::PosInt<MAX_PUBLIC_MODULUS_WORDS>;
        }
