                    let mut s2_1 = lsx_vldi::<0>();
                    let mut s2_2 = lsx_vldi::<0>();
                    let mut s2_3 = lsx_vldi::<0>();

                    let mut s2_4 = lsx_vldi::<0>();
                    let mut s2_5 = lsx_vldi::<0>();
