                    b_v = u32x4_add(b_v, mad);

                    a_v = u32x4_add(a_v, u32x4_extadd_quarters_u8x16(v_hi));
                    let mad = i32x4_dot_i8x16(v_hi, weight_hi_v);
                    b_v = u32x4_add(b_v, mad);
