    mod hash_calc {

    use crate::android_debug_bridge::zlib_rs::deflate::{State, HASH_SIZE, STD_MIN_MATCH};

    #[derive(Debug, Clone, Copy)]
    pub enum HashCalcVariant {
        Standard,
        Roll,
    }

    impl HashCalcVariant {

        pub fn for_max_chain_length(max_chain_length: u16) -> Self {
            if max_chain_length > 1024 {
                HashCalcVariant::Roll
            } else {
                HashCalcVariant::Standard
            }
        }
    }

    pub struct StandardHashCalc;

    impl StandardHashCalc {
        const HASH_CALC_OFFSET: usize = 0;

        const HASH_CALC_MASK: u32 = (HASH_SIZE - 1) as u32;

        fn hash_calc(_: u32, val: u32) -> u32 {
            const HASH_SLIDE: u32 = 16;
            val.wrapping_mul(2654435761) >> HASH_SLIDE
        }

        pub fn update_hash(h: u32, val: u32) -> u32 {
            Self::hash_calc(h, val) & Self::HASH_CALC_MASK
        }

        #[inline]
        pub fn quick_insert_string(state: &mut State, string: usize) -> u16 {
            let slice = &state.window.filled()[string + Self::HASH_CALC_OFFSET..];
            let val = u32::from_le_bytes(slice[..4].try_into().unwrap());

            Self::quick_insert_value(state, string, val)
        }

        #[inline]
        pub fn quick_insert_value(state: &mut State, string: usize, val: u32) -> u16 {
            let hm = Self::update_hash(0, val) as usize;

            let head = state.head.as_slice()[hm];
            if head != string as u16 {
                let w_mask = state.w_mask();
                state.prev.as_mut_slice()[string & w_mask] = head;
                state.head.as_mut_slice()[hm] = string as u16;
            }

            head
        }

        pub fn insert_string(state: &mut State, string: usize, count: usize) {
            let slice = &state.window.filled()[string + Self::HASH_CALC_OFFSET..];

            let slice = &slice[..Ord::min(slice.len(), count + 3)];

            let w_mask = state.w_mask();
            for (i, w) in slice.windows(4).enumerate() {
                let idx = string as u16 + i as u16;

                let val = u32::from_le_bytes(w.try_into().unwrap());

                let hm = Self::update_hash(0, val) as usize;

                let head = state.head.as_slice()[hm];
                if head != idx {
                    state.prev.as_mut_slice()[idx as usize & w_mask] = head;
                    state.head.as_mut_slice()[hm] = idx;
                }
            }
        }
    }

    pub struct RollHashCalc;

    impl RollHashCalc {
        const HASH_CALC_OFFSET: usize = STD_MIN_MATCH - 1;

        const HASH_CALC_MASK: u32 = (1 << 15) - 1;

        fn hash_calc(h: u32, val: u32) -> u32 {
            const HASH_SLIDE: u32 = 5;
            (h << HASH_SLIDE) ^ val
        }

        pub fn update_hash(h: u32, val: u32) -> u32 {
            Self::hash_calc(h, val) & Self::HASH_CALC_MASK
        }

        pub fn quick_insert_string(state: &mut State, string: usize) -> u16 {
            let val = state.window.filled()[string + Self::HASH_CALC_OFFSET] as u32;

            state.ins_h = Self::hash_calc(state.ins_h, val);
            state.ins_h &= Self::HASH_CALC_MASK;

            let hm = state.ins_h as usize;

            let head = state.head.as_slice()[hm];
            if head != string as u16 {
                let w_mask = state.w_mask();
                state.prev.as_mut_slice()[string & w_mask] = head;
                state.head.as_mut_slice()[hm] = string as u16;
            }

            head
        }

        pub fn insert_string(state: &mut State, string: usize, count: usize) {
            let slice = &state.window.filled()[string + Self::HASH_CALC_OFFSET..][..count];

            let w_mask = state.w_mask();
            for (i, val) in slice.iter().copied().enumerate() {
                let idx = string as u16 + i as u16;

                state.ins_h = Self::hash_calc(state.ins_h, val as u32);
                state.ins_h &= Self::HASH_CALC_MASK;
                let hm = state.ins_h as usize;

                let head = state.head.as_slice()[hm];
                if head != idx {
                    state.prev.as_mut_slice()[idx as usize & w_mask] = head;
                    state.head.as_mut_slice()[hm] = idx;
                }
            }
        }
    }

    }
    mod longest_match {
    use crate::android_debug_bridge::zlib_rs::deflate::{Pos, State, MIN_LOOKAHEAD, STD_MAX_MATCH, STD_MIN_MATCH};

    const EARLY_EXIT_TRIGGER_LEVEL: i8 = 5;

    pub fn longest_match(state: &crate::android_debug_bridge::zlib_rs::deflate::State, cur_match: u16) -> (usize, u16) {
        longest_match_help::<false>(state, cur_match)
    }

    pub fn longest_match_slow(state: &crate::android_debug_bridge::zlib_rs::deflate::State, cur_match: u16) -> (usize, u16) {
        longest_match_help::<true>(state, cur_match)
    }

    fn longest_match_help<const SLOW: bool>(
        state: &crate::android_debug_bridge::zlib_rs::deflate::State,
        mut cur_match: u16,
    ) -> (usize, u16) {
        let mut match_start = state.match_start;

        let strstart = state.strstart;
        let wmask = state.w_mask();
        let window = state.window.filled();
        let scan = &window[strstart..];

        let prev = &state.prev.as_slice()[..=wmask];
        let mut limit: Pos;
        let limit_base: Pos;
        let early_exit: bool;

        let mut chain_length: u16;
        let mut best_len: usize;

        let lookahead = state.lookahead;
        let mut match_offset = 0;

        macro_rules! goto_next_in_chain {
            () => {
                chain_length -= 1;
                if chain_length > 0 {
                    cur_match = prev[cur_match as usize & wmask];

                    if cur_match > limit {
                        continue;
                    }
                }

                return (best_len, match_start);
            };
        }

        assert_eq!(STD_MAX_MATCH, 258, "Code too clever");

        best_len = if state.prev_length > 0 {
            state.prev_length as usize
        } else {
            STD_MIN_MATCH - 1
        };

        let mut offset = best_len - 1;
        if best_len >= core::mem::size_of::<u32>() {
            offset -= 2;
            if best_len >= core::mem::size_of::<u64>() {
                offset -= 4;
            }
        }

        let mut mbase_start = window.as_ptr();
        let mut mbase_end = window[offset..].as_ptr();

        chain_length = state.max_chain_length;
        if best_len >= state.good_match as usize {
            chain_length >>= 2;
        }
        let nice_match = state.nice_match;

        limit = strstart.saturating_sub(state.max_dist()) as Pos;

        if SLOW {
            limit_base = limit;

            if best_len >= STD_MIN_MATCH {

                let mut pos: Pos;

                let Some([_cur_match, scan1, scan2, scanrest @ ..]) = scan.get(..best_len + 1) else {
                    panic!("invalid scan");
                };

                let mut hash = 0;
                hash = state.update_hash(hash, *scan1 as u32);
                hash = state.update_hash(hash, *scan2 as u32);

                for (i, b) in scanrest.iter().enumerate() {
                    hash = state.update_hash(hash, *b as u32);

                    pos = state.head.as_slice()[hash as usize];
                    if pos < cur_match {
                        match_offset = (i + 1) as Pos;
                        cur_match = pos;
                    }
                }

                limit = limit_base + match_offset;
                if cur_match <= limit {
                    return break_matching(state, best_len, match_start);
                }

                mbase_start = mbase_start.wrapping_sub(match_offset as usize);
                mbase_end = mbase_end.wrapping_sub(match_offset as usize);
            }

            early_exit = false;
        } else {

            limit_base = 0;
            early_exit = state.level < EARLY_EXIT_TRIGGER_LEVEL;
        }

        let scan_start = window[strstart..].as_ptr();
        let mut scan_end = window[strstart + offset..].as_ptr();

        assert!(
            strstart <= state.window_size.saturating_sub(MIN_LOOKAHEAD),
            "need lookahead"
        );

        loop {
            if cur_match as usize >= strstart {
                break;
            }

            #[inline(always)]
            unsafe fn memcmp_n_ptr<const N: usize>(src0: *const u8, src1: *const u8) -> bool { unsafe {
                unsafe {
                    let src0_cmp = core::ptr::read(src0 as *const [u8; N]);
                    let src1_cmp = core::ptr::read(src1 as *const [u8; N]);
                    src0_cmp == src1_cmp
                }
            }}

            #[inline(always)]
            unsafe fn is_match<const N: usize>(
                cur_match: u16,
                mbase_start: *const u8,
                mbase_end: *const u8,
                scan_start: *const u8,
                scan_end: *const u8,
            ) -> bool { unsafe {
                let be = mbase_end.wrapping_add(cur_match as usize);
                let bs = mbase_start.wrapping_add(cur_match as usize);
                unsafe { memcmp_n_ptr::<N>(be, scan_end) && memcmp_n_ptr::<N>(bs, scan_start) }
            }}

            let mut len = 0;
            unsafe {
                if best_len < core::mem::size_of::<u64>() {
                    let scan_val = u64::from_ne_bytes(
                        core::slice::from_raw_parts(scan_start, 8)
                            .try_into()
                            .unwrap(),
                    );
                    loop {
                        let bs = mbase_start.wrapping_add(cur_match as usize);
                        let match_val =
                            u64::from_ne_bytes(core::slice::from_raw_parts(bs, 8).try_into().unwrap());
                        let cmp = scan_val ^ match_val;
                        if cmp == 0 {

                            break;
                        }

                        let cmp_len = cmp.to_le().trailing_zeros() as usize / 8;
                        if cmp_len > best_len {

                            len = cmp_len;
                            break;
                        }
                        goto_next_in_chain!();
                    }
                } else {
                    loop {
                        if is_match::<8>(cur_match, mbase_start, mbase_end, scan_start, scan_end) {
                            break;
                        }

                        goto_next_in_chain!();
                    }
                }
            }

            if len == 0 {
                len = {

                    let src1 = unsafe {
                        core::slice::from_raw_parts(
                            mbase_start.wrapping_add(cur_match as usize + 2),
                            256,
                        )
                    };

                    crate::android_debug_bridge::zlib_rs::deflate::compare256::compare256_slice(&scan[2..], src1) + 2
                };
            }

            assert!(
                scan.as_ptr() as usize + len <= window.as_ptr() as usize + (state.window_size - 1),
                "wild scan"
            );

            if len > best_len {
                match_start = cur_match - match_offset;

                if len >= lookahead {
                    return (lookahead, match_start);
                }
                best_len = len;
                if best_len >= nice_match as usize {
                    return (best_len, match_start);
                }

                offset = best_len - 1;
                if best_len >= core::mem::size_of::<u32>() {
                    offset -= 2;
                    if best_len >= core::mem::size_of::<u64>() {
                        offset -= 4;
                    }
                }

                scan_end = window[strstart + offset..].as_ptr();

                if SLOW && len > STD_MIN_MATCH && match_start as usize + len < strstart {
                    let mut pos: Pos;

                    cur_match -= match_offset;
                    match_offset = 0;
                    let mut next_pos = cur_match;

                    for i in 0..=len - STD_MIN_MATCH {
                        pos = prev[(cur_match as usize + i) & wmask];
                        if pos < next_pos {

                            if pos <= limit_base + i as Pos {
                                return break_matching(state, best_len, match_start);
                            }
                            next_pos = pos;
                            match_offset = i as Pos;
                        }
                    }

                    cur_match = next_pos;

                    let [scan0, scan1, scan2, ..] = scan[len - (STD_MIN_MATCH + 1)..] else {
                        panic!("index out of bounds");
                    };

                    let mut hash = 0;
                    hash = state.update_hash(hash, scan0 as u32);
                    hash = state.update_hash(hash, scan1 as u32);
                    hash = state.update_hash(hash, scan2 as u32);

                    pos = state.head.as_slice()[hash as usize];
                    if pos < cur_match {
                        match_offset = (len - (STD_MIN_MATCH + 1)) as Pos;
                        if pos <= limit_base + match_offset {
                            return break_matching(state, best_len, match_start);
                        }
                        cur_match = pos;
                    }

                    limit = limit_base + match_offset;
                    mbase_start = window.as_ptr().wrapping_sub(match_offset as usize);
                    mbase_end = mbase_start.wrapping_add(offset);
                    continue;
                }

                mbase_end = mbase_start.wrapping_add(offset);
            } else if !SLOW && early_exit {

                break;
            }

            goto_next_in_chain!();
        }

        (best_len, match_start)
    }

    fn break_matching(state: &State, best_len: usize, match_start: u16) -> (usize, u16) {
        (Ord::min(best_len, state.lookahead), match_start)
    }

    }
    mod pending {
    use core::{marker::PhantomData, mem::MaybeUninit};

    use crate::android_debug_bridge::zlib_rs::weak_slice::WeakSliceMut;

    pub struct Pending<'a> {

        buf: WeakSliceMut<'a, MaybeUninit<u8>>,

        out: usize,

        pub(in crate::android_debug_bridge::zlib_rs) pending: usize,

        _marker: PhantomData<&'a mut [u8]>,
    }

    impl<'a> Pending<'a> {
        pub fn reset_keep(&mut self) {

            self.pending = 0;
        }

        pub fn pending(&self) -> &[u8] {
            let slice = &self.buf.as_slice()[self.out..][..self.pending];

            unsafe { &*(slice as *const [MaybeUninit<u8>] as *const [u8]) }
        }

        pub(in crate::android_debug_bridge::zlib_rs) fn remaining(&self) -> usize {
            self.buf.len() - (self.out + self.pending)
        }

        pub(in crate::android_debug_bridge::zlib_rs) fn capacity(&self) -> usize {
            self.buf.len()
        }

        #[inline(always)]
        #[track_caller]

        pub fn advance(&mut self, number_of_bytes: usize) {
            debug_assert!(self.pending >= number_of_bytes);

            self.out = self.out.wrapping_add(number_of_bytes);
            self.pending -= number_of_bytes;

            if self.pending == 0 {
                self.out = 0;
            }
        }

        #[inline(always)]
        #[track_caller]
        pub fn rewind(&mut self, n: usize) {
            assert!(n <= self.pending, "rewinding past then start");

            self.pending -= n;

            if self.pending == 0 {
                self.out = 0;
            }
        }

        #[inline(always)]
        #[track_caller]
        pub fn extend(&mut self, buf: &[u8]) {
            assert!(
                self.remaining() >= buf.len(),
                "buf.len() must fit in remaining()"
            );

            let buf = unsafe { &*(buf as *const [u8] as *const [MaybeUninit<u8>]) };

            self.buf.as_mut_slice()[self.out + self.pending..][..buf.len()].copy_from_slice(buf);

            self.pending += buf.len();
        }

        pub(in crate::android_debug_bridge::zlib_rs) unsafe fn from_raw_parts(ptr: *mut MaybeUninit<u8>, len: usize) -> Self { unsafe {
            let buf = unsafe { WeakSliceMut::from_raw_parts_mut(ptr, len) };

            Self {
                buf,
                out: 0,
                pending: 0,
                _marker: PhantomData,
            }
        }}

        pub(in crate::android_debug_bridge::zlib_rs) unsafe fn clone_to(&self, ptr: *mut u8) -> Self { unsafe {
            let ptr = ptr.cast::<MaybeUninit<u8>>();
            unsafe { ptr.copy_from_nonoverlapping(self.buf.as_ptr(), self.buf.len()) };
            Self {
                buf: unsafe { WeakSliceMut::from_raw_parts_mut(ptr, self.buf.len()) },
                out: self.out,
                pending: self.pending,
                _marker: PhantomData,
            }
        }}
    }

    }
    mod slide_hash {
    pub fn slide_hash(state: &mut crate::android_debug_bridge::zlib_rs::deflate::State) {
        let wsize = state.w_size as u16;

        slide_hash_chain(state.head.as_mut_slice(), wsize);
        slide_hash_chain(state.prev.as_mut_slice(), wsize);
    }

    fn slide_hash_chain(table: &mut [u16], wsize: u16) {
        #[cfg(target_arch = "x86_64")]
        if crate::android_debug_bridge::zlib_rs::cpu_features::is_enabled_avx2_and_bmi2() {

            return unsafe { avx2::slide_hash_chain(table, wsize) };
        }

        #[cfg(target_arch = "aarch64")]
        if crate::android_debug_bridge::zlib_rs::cpu_features::is_enabled_neon() {
            return unsafe { neon::slide_hash_chain(table, wsize) };
        }

        #[cfg(all(target_arch = "loongarch64", any()))]
        if crate::android_debug_bridge::zlib_rs::cpu_features::is_enabled_lsx() {
            return unsafe { lsx::slide_hash_chain(table, wsize) };
        }

        #[cfg(target_arch = "wasm32")]
        if crate::android_debug_bridge::zlib_rs::cpu_features::is_enabled_simd128() {

            return unsafe { wasm::slide_hash_chain(table, wsize) };
        }

        rust::slide_hash_chain(table, wsize);
    }

    #[inline(always)]
    fn generic_slide_hash_chain<const N: usize>(table: &mut [u16], wsize: u16) {
        debug_assert_eq!(table.len() % N, 0);

        for chunk in table.chunks_exact_mut(N) {
            for m in chunk.iter_mut() {
                *m = m.saturating_sub(wsize);
            }
        }
    }

    mod rust {
        pub fn slide_hash_chain(table: &mut [u16], wsize: u16) {

            super::generic_slide_hash_chain::<32>(table, wsize);
        }
    }

    #[cfg(target_arch = "x86_64")]
    mod avx2 {

        #[target_feature(enable = "avx2")]
        #[target_feature(enable = "bmi2")]
        #[target_feature(enable = "bmi1")]
        pub unsafe fn slide_hash_chain(table: &mut [u16], wsize: u16) { unsafe {

            super::generic_slide_hash_chain::<64>(table, wsize);
        }}
    }

    #[cfg(target_arch = "aarch64")]
    mod neon {

        #[target_feature(enable = "neon")]
        pub unsafe fn slide_hash_chain(table: &mut [u16], wsize: u16) { unsafe {

            super::generic_slide_hash_chain::<32>(table, wsize);
        }}
    }

    #[cfg(all(target_arch = "loongarch64", any()))]
    mod lsx {

        #[target_feature(enable = "lsx")]
        pub unsafe fn slide_hash_chain(table: &mut [u16], wsize: u16) { unsafe {

            super::generic_slide_hash_chain::<32>(table, wsize);
        }}
    }

    #[cfg(target_arch = "wasm32")]
    mod wasm {

        #[target_feature(enable = "simd128")]
        pub unsafe fn slide_hash_chain(table: &mut [u16], wsize: u16) { unsafe {

            super::generic_slide_hash_chain::<32>(table, wsize);
        }}
    }

    }
    mod sym_buf {

    use crate::android_debug_bridge::zlib_rs::weak_slice::WeakSliceMut;

    pub(in crate::android_debug_bridge::zlib_rs) struct SymBuf<'a> {
        buf: WeakSliceMut<'a, u8>,
        filled: usize,
    }

    impl<'a> SymBuf<'a> {
        #[inline]
        pub fn iter(&self) -> impl Iterator<Item = (u16, u8)> + '_ {
            self.buf.as_slice()[..self.filled]
                .chunks_exact(3)
                .map(|chunk| match *chunk {
                    [dist_low, dist_high, lc] => (u16::from_le_bytes([dist_low, dist_high]), lc),
                    _ => unreachable!("chunks are exactly 3 elements wide"),
                })
        }

        #[inline]
        pub fn should_flush_block(&self) -> bool {
            self.filled == self.buf.len() - 3
        }

        #[inline]
        pub fn is_empty(&self) -> bool {
            self.filled == 0
        }

        #[inline]
        pub fn clear(&mut self) {
            self.buf.as_mut_slice().fill(0);
            self.filled = 0;
        }

        #[inline(always)]
        pub fn push_lit(&mut self, byte: u8) {

            self.buf.as_mut_slice()[self.filled + 2] = byte;

            self.filled += 3;
        }

        #[inline(always)]
        pub fn push_dist(&mut self, dist: u16, len: u8) {
            let buf = &mut self.buf.as_mut_slice()[self.filled..][..3];

            unsafe {
                core::ptr::write_unaligned(buf.as_mut_ptr().cast::<[u8; 2]>(), dist.to_le_bytes())
            };
            buf[2] = len;

            self.filled += 3;
        }

        pub(in crate::android_debug_bridge::zlib_rs) unsafe fn from_raw_parts(ptr: *mut u8, lit_bufsize: usize) -> Self { unsafe {
            Self {
                buf: unsafe { WeakSliceMut::from_raw_parts_mut(ptr, lit_bufsize * 3) },
                filled: 0,
            }
        }}

        pub(in crate::android_debug_bridge::zlib_rs) unsafe fn clone_to(&self, ptr: *mut u8) -> Self { unsafe {
            unsafe { ptr.copy_from_nonoverlapping(self.buf.as_ptr(), self.buf.len()) };
            Self {
                buf: unsafe { WeakSliceMut::from_raw_parts_mut(ptr, self.buf.len()) },
                filled: self.filled,
            }
        }}
    }

    }
