            #[derive(Clone, Debug)]
            pub(in crate::android_debug_bridge::rustls) struct ClientHelloPayload {
                pub(in crate::android_debug_bridge::rustls) client_version: ProtocolVersion,
                pub(in crate::android_debug_bridge::rustls) random: Random,
                pub(in crate::android_debug_bridge::rustls) session_id: SessionId,
                pub(in crate::android_debug_bridge::rustls) cipher_suites: Vec<CipherSuite>,
                pub(in crate::android_debug_bridge::rustls) compression_methods: Vec<Compression>,
                pub(in crate::android_debug_bridge::rustls) extensions:
                    Box<ClientExtensions<'static>>,
            }

            impl ClientHelloPayload {
                pub(in crate::android_debug_bridge::rustls) fn ech_inner_encoding(
                    &self,
                    to_compress: Vec<ExtensionType>,
                ) -> Vec<u8> {
                    let mut bytes = Vec::new();
                    self.payload_encode(&mut bytes, Encoding::EchInnerHello { to_compress });
                    bytes
                }

                pub(in crate::android_debug_bridge::rustls) fn payload_encode(
                    &self,
                    bytes: &mut Vec<u8>,
                    purpose: Encoding,
                ) {
                    self.client_version.encode(bytes);
                    self.random.encode(bytes);

                    match purpose {
                        Encoding::EchInnerHello { .. } => SessionId::empty().encode(bytes),
                        _ => self.session_id.encode(bytes),
                    }

                    self.cipher_suites.encode(bytes);
                    self.compression_methods.encode(bytes);

                    let to_compress = match purpose {
                        Encoding::EchInnerHello { to_compress } if !to_compress.is_empty() => {
                            to_compress
                        }
                        _ => {
                            self.extensions.encode(bytes);
                            return;
                        }
                    };

                    let mut compressed = self.extensions.clone();

                    for e in &to_compress {
                        compressed.clear(*e);
                    }

                    compressed.encrypted_client_hello_outer = Some(to_compress);

                    compressed.encode(bytes);
                }

                pub(in crate::android_debug_bridge::rustls) fn has_keyshare_extension_with_duplicates(
                    &self,
                ) -> bool {
                    self.key_shares
                        .as_ref()
                        .map(|entries| {
                            has_duplicates::<_, _, u16>(
                                entries.iter().map(|kse| u16::from(kse.group)),
                            )
                        })
                        .unwrap_or_default()
                }

                pub(in crate::android_debug_bridge::rustls) fn has_certificate_compression_extension_with_duplicates(
                    &self,
                ) -> bool {
                    if let Some(algs) = &self.certificate_compression_algorithms {
                        has_duplicates::<_, _, u16>(algs.iter().copied())
                    } else {
                        false
                    }
                }
            }

            impl Codec<'_> for ClientHelloPayload {
                fn encode(&self, bytes: &mut Vec<u8>) {
                    self.payload_encode(bytes, Encoding::Standard)
                }

                fn read(r: &mut Reader<'_>) -> Result<Self, InvalidMessage> {
                    r.all("ClientHelloPayload", |r| {
                        Ok(Self {
                            client_version: ProtocolVersion::read(r)?,
                            random: Random::read(r)?,
                            session_id: SessionId::read(r)?,
                            cipher_suites: Vec::read(r)?,
                            compression_methods: Vec::read(r)?,
                            extensions: Box::new(ClientExtensions::read(r)?.into_owned()),
                        })
                    })
                }
            }

            impl Deref for ClientHelloPayload {
                type Target = ClientExtensions<'static>;
                fn deref(&self) -> &Self::Target {
                    &self.extensions
                }
            }

            impl DerefMut for ClientHelloPayload {
                fn deref_mut(&mut self) -> &mut Self::Target {
                    &mut self.extensions
                }
            }

