                pub(in crate::android_debug_bridge::rustls) fn all<
                    T,
                    E: From<InvalidMessage>,
                    F: FnOnce(&mut Self) -> Result<T, E>,
                >(
                    &mut self,
                    type_name: &'static str,
                    f: F,
                ) -> Result<T, E> {
                    let value = f(self)?;
                    match self.any_left() {
                        true => Err(InvalidMessage::TrailingData(type_name).into()),
                        false => Ok(value),
                    }
                }

