                pub(in crate::android_debug_bridge::rustls) fn input_quic(
                    &mut self,
                    buf: &mut [u8],
                ) -> Result<(), InvalidMessage> {
                    let bounds = self.processed..buf.len();
                    self.processed += bounds.len();
                    self.input_message(ProtocolVersion::TLSv1_3, bounds, buf);
                    self.coalesce(buf)?;
                    Ok(())
                }

                pub(in crate::android_debug_bridge::rustls) fn input_message(
                    &mut self,
                    version: ProtocolVersion,
                    bounds: Range<usize>,
                    buf: &[u8],
                ) {
                    let Some(payload) = buf.get(bounds.start..bounds.end) else {
                        return;
                    };

                    if let Some(_last_incomplete) =
                        self.spans.back().filter(|span| !span.is_complete())
                    {
                        self.spans.push_back(FragmentSpan {
                            version,
                            size: None,
                            bounds,
                        });
                        return;
                    }

                    let iter = DissectHandshakeIter {
                        version,
                        payload,
                        bounds,
                    };

                    for span in iter {
                        self.too_large |= span.size.unwrap_or_default() > MAX_HANDSHAKE_SIZE;
                        self.spans.push_back(span);
                    }
                }

                pub(in crate::android_debug_bridge::rustls) fn coalesce(
                    &mut self,
                    containing_buffer: &mut [u8],
                ) -> Result<(), InvalidMessage> {
                    loop {
                        if self.too_large {
                            return Err(InvalidMessage::HandshakePayloadTooLarge);
                        }

                        let limit = self.spans.len().saturating_sub(1);
                        let iter = self.spans.iter();
                        let Some(index) = iter
                            .enumerate()
                            .take(limit)
                            .find_map(|(i, span)| (!span.is_complete()).then_some(i))
                        else {
                            return Ok(());
                        };

                        let Some(second) = self.spans.remove(index + 1) else {
                            return Ok(());
                        };

                        let Some(mut first) = self.spans.remove(index) else {
                            self.spans.insert(index + 1, second);
                            return Ok(());
                        };

                        let len = second.bounds.len();
                        let target = Range {
                            start: first.bounds.end,
                            end: first.bounds.end + len,
                        };

                        let mut coalescer = Coalescer::new(containing_buffer);
                        coalescer.copy_within(second.bounds, target);
                        let delocator = coalescer.delocator();

                        first.bounds.end += len;

                        let record = Record {
                            typ: ContentType::Handshake,
                            version: EncodableVersion::Legacy(first.version),
                            payload: delocator.slice_from_range(&first.bounds),
                        };

                        let iter = DissectHandshakeIter {
                            version: first.version,
                            payload: record.payload,
                            bounds: first.bounds.start..first.bounds.end,
                        };

                        for (i, span) in iter.enumerate() {
                            self.too_large |= span.size.unwrap_or_default() > MAX_HANDSHAKE_SIZE;
                            self.spans.insert(index + i, span);
                        }
                    }
                }

                pub(in crate::android_debug_bridge::rustls) fn record<'b>(
                    &mut self,
                    next_span: FragmentSpan,
                    containing_buffer: &'b [u8],
                ) -> Record<&'b [u8]> {
                    if self.spans.is_empty() {
                        self.discard = self.processed;
                    }

                    Record {
                        typ: ContentType::Handshake,
                        version: EncodableVersion::Legacy(next_span.version),
                        payload: Delocator::new(containing_buffer)
                            .slice_from_range(&next_span.bounds),
                    }
                }

                pub(in crate::android_debug_bridge::rustls) fn complete_span(
                    &mut self,
                ) -> Option<FragmentSpan> {
                    match self.spans.front() {
                        Some(span) if span.is_complete() => self.spans.pop_front(),
                        _ => None,
                    }
                }

                #[inline]
                pub(in crate::android_debug_bridge::rustls) fn take_discard(&mut self) -> usize {
                    let discard = mem::take(&mut self.discard);
                    self.processed = self.processed.saturating_sub(discard);
                    for span in &mut self.spans {
                        span.bounds.start = span.bounds.start.saturating_sub(discard);
                        span.bounds.end = span.bounds.end.saturating_sub(discard);
                    }
                    discard
                }

                #[inline]
                pub(in crate::android_debug_bridge::rustls) fn discard_processed(&mut self) {
                    self.discard = self.processed;
                }

                #[inline]
                pub(in crate::android_debug_bridge::rustls) fn set_discard(
                    &mut self,
                    discard: usize,
                ) {
                    self.discard = discard;
                }

