            impl Fragmenter {
                pub(in crate::android_debug_bridge::rustls) fn fragment<'a>(
                    &self,
                    typ: ContentType,
                    version: EncodableVersion,
                    payload: OutboundPlain<'a>,
                    encryption_overhead: usize,
                ) -> impl ExactSizeIterator<Item = Record<OutboundPlain<'a>>> + use<'a>
                {
                    let max_plaintext =
                        NonZeroUsize::new(self.max_frag.get().saturating_sub(encryption_overhead))
                            .unwrap_or(NonZeroUsize::MIN);
                    Chunker::new(payload, max_plaintext).map(move |payload| Record {
                        typ,
                        version,
                        payload,
                    })
                }

                pub(in crate::android_debug_bridge::rustls) fn set_max_fragment_size(
                    &mut self,
                    max_fragment_size: Option<usize>,
                ) -> Result<(), Error> {
                    self.max_frag = match max_fragment_size {
                        Some(sz @ 32..=MAX_FRAGMENT_SIZE) => {
                            NonZeroUsize::new(sz - PACKET_OVERHEAD).unwrap()
                        }
                        None => MAX_FRAGMENT_LEN,
                        _ => return Err(Error::BadMaxFragmentSize),
                    };
                    Ok(())
                }
            }

            impl Default for Fragmenter {
                fn default() -> Self {
                    Self {
                        max_frag: MAX_FRAGMENT_LEN,
                    }
                }
            }

            struct Chunker<'a> {
                payload: OutboundPlain<'a>,
                limit: NonZeroUsize,
            }

            impl<'a> Chunker<'a> {
                fn new(payload: OutboundPlain<'a>, limit: NonZeroUsize) -> Self {
                    Self { payload, limit }
                }
            }

            impl<'a> Iterator for Chunker<'a> {
                type Item = OutboundPlain<'a>;

                fn next(&mut self) -> Option<Self::Item> {
                    if self.payload.is_empty() {
                        return None;
                    }

                    let (before, after) = self.payload.split_at(self.limit.get());
                    self.payload = after;
                    Some(before)
                }
            }

            impl ExactSizeIterator for Chunker<'_> {
                fn len(&self) -> usize {
                    self.payload.len().div_ceil(self.limit.get())
                }
            }

