            extension_struct! {

                pub(in crate::android_debug_bridge::rustls) struct HelloRetryRequestExtensions<'a> {
                    ExtensionType::KeyShare =>
                        pub(in crate::android_debug_bridge::rustls) key_share: Option<NamedGroup>,

                    ExtensionType::Cookie =>
                        pub(in crate::android_debug_bridge::rustls) cookie: Option<SizedPayload<'a, u16, NonEmpty>>,

                    ExtensionType::SupportedVersions =>
                        pub(in crate::android_debug_bridge::rustls) supported_versions: Option<ProtocolVersion>,

                    ExtensionType::EncryptedClientHello =>
                        pub(in crate::android_debug_bridge::rustls) encrypted_client_hello: Option<Payload<'a>>,
                } + {

                    pub(in crate::android_debug_bridge::rustls) order: Option<Vec<ExtensionType>>,
                }
            }

            impl HelloRetryRequestExtensions<'_> {
                fn into_owned(self) -> HelloRetryRequestExtensions<'static> {
                    let Self {
                        key_share,
                        cookie,
                        supported_versions,
                        encrypted_client_hello,
                        order,
                    } = self;
                    HelloRetryRequestExtensions {
                        key_share,
                        cookie: cookie.map(|x| x.into_owned()),
                        supported_versions,
                        encrypted_client_hello: encrypted_client_hello.map(|x| x.into_owned()),
                        order,
                    }
                }
            }

            impl<'a> Codec<'a> for HelloRetryRequestExtensions<'a> {
                fn encode(&self, bytes: &mut Vec<u8>) {
                    let extensions = LengthPrefixedBuffer::new(ListLength::U16, bytes);

                    for ext in self.order.as_deref().unwrap_or(Self::ALL_EXTENSIONS) {
                        self.encode_one(*ext, extensions.buf);
                    }
                }

                fn read(r: &mut Reader<'a>) -> Result<Self, InvalidMessage> {
                    let mut out = Self::default();

                    let mut order = vec![];

                    let len = usize::from(u16::read(r)?);
                    let mut sub = r.sub(len)?;

                    while sub.any_left() {
                        let typ = out.read_one(&mut sub, |_unk| {
                            Err(InvalidMessage::UnknownHelloRetryRequestExtension)
                        })?;

                        order.push(typ);
                    }

                    out.order = Some(order);
                    Ok(out)
                }
            }

            #[derive(Clone, Debug)]
            pub(in crate::android_debug_bridge::rustls) struct HelloRetryRequest {
                pub(in crate::android_debug_bridge::rustls) legacy_version: ProtocolVersion,
                pub(in crate::android_debug_bridge::rustls) session_id: SessionId,
                pub(in crate::android_debug_bridge::rustls) cipher_suite: CipherSuite,
                pub(in crate::android_debug_bridge::rustls) extensions:
                    HelloRetryRequestExtensions<'static>,
            }

            impl Codec<'_> for HelloRetryRequest {
                fn encode(&self, bytes: &mut Vec<u8>) {
                    self.payload_encode(bytes, Encoding::Standard)
                }

                fn read(r: &mut Reader<'_>) -> Result<Self, InvalidMessage> {
                    let session_id = SessionId::read(r)?;
                    let cipher_suite = CipherSuite::read(r)?;
                    let compression = Compression::read(r)?;

                    if compression != Compression::Null {
                        return Err(InvalidMessage::UnsupportedCompression);
                    }

                    Ok(Self {
                        legacy_version: ProtocolVersion(0),
                        session_id,
                        cipher_suite,
                        extensions: HelloRetryRequestExtensions::read(r)?.into_owned(),
                    })
                }
            }

            impl HelloRetryRequest {
                pub(super) fn payload_encode(&self, bytes: &mut Vec<u8>, purpose: Encoding) {
                    self.legacy_version.encode(bytes);
                    HELLO_RETRY_REQUEST_RANDOM.encode(bytes);
                    self.session_id.encode(bytes);
                    self.cipher_suite.encode(bytes);
                    Compression::Null.encode(bytes);

                    match purpose {
                        Encoding::EchConfirmation
                            if self.extensions.encrypted_client_hello.is_some() =>
                        {
                            let hrr_confirmation = [0u8; 8];
                            HelloRetryRequestExtensions {
                                encrypted_client_hello: Some(Payload::Borrowed(&hrr_confirmation)),
                                ..self.extensions.clone()
                            }
                            .encode(bytes);
                        }
                        _ => self.extensions.encode(bytes),
                    }
                }
            }

            impl Deref for HelloRetryRequest {
                type Target = HelloRetryRequestExtensions<'static>;
                fn deref(&self) -> &Self::Target {
                    &self.extensions
                }
            }

            impl DerefMut for HelloRetryRequest {
                fn deref_mut(&mut self) -> &mut Self::Target {
                    &mut self.extensions
                }
            }

