            #[derive(Debug)]
            pub(in crate::android_debug_bridge::rustls) struct CertificatePayloadTls13<'a> {
                pub(in crate::android_debug_bridge::rustls) context: SizedPayload<'a, u8>,
                pub(in crate::android_debug_bridge::rustls) entries: Vec<CertificateEntry<'a>>,
            }

            impl<'a> CertificatePayloadTls13<'a> {
                pub(in crate::android_debug_bridge::rustls) fn new(
                    certs: impl Iterator<Item = CertificateDer<'a>>,
                    ocsp_response: Option<&'a [u8]>,
                ) -> Self {
                    let ocsp_response = match ocsp_response {
                        Some([]) | None => None,
                        Some(bytes) => Some(bytes),
                    };

                    Self {
                        context: SizedPayload::from(Payload::Borrowed(&[])),
                        entries: certs
                            .zip(
                                ocsp_response
                                    .into_iter()
                                    .map(Some)
                                    .chain(iter::repeat(None)),
                            )
                            .map(|(cert, ocsp)| {
                                let mut e = CertificateEntry::new(cert);
                                if let Some(ocsp) = ocsp {
                                    e.extensions.status = Some(CertificateStatus::new(ocsp));
                                }
                                e
                            })
                            .collect(),
                    }
                }

                pub(super) fn into_owned(self) -> CertificatePayloadTls13<'static> {
                    CertificatePayloadTls13 {
                        context: self.context.into_owned(),
                        entries: self
                            .entries
                            .into_iter()
                            .map(CertificateEntry::into_owned)
                            .collect(),
                    }
                }

                pub(in crate::android_debug_bridge::rustls) fn end_entity_ocsp(&self) -> Vec<u8> {
                    let Some(entry) = self.entries.first() else {
                        return vec![];
                    };
                    entry
                        .extensions
                        .status
                        .as_ref()
                        .map(|status| status.ocsp_response.to_vec())
                        .unwrap_or_default()
                }

                pub(in crate::android_debug_bridge::rustls) fn into_certificate_chain(
                    self,
                ) -> CertificateChain<'a> {
                    CertificateChain(self.entries.into_iter().map(|e| e.cert).collect())
                }
            }

            impl<'a> Codec<'a> for CertificatePayloadTls13<'a> {
                fn encode(&self, bytes: &mut Vec<u8>) {
                    self.context.encode(bytes);
                    self.entries.encode(bytes);
                }

                fn read(r: &mut Reader<'a>) -> Result<Self, InvalidMessage> {
                    Ok(Self {
                        context: SizedPayload::read(r)?.into_owned(),
                        entries: Vec::read(r)?,
                    })
                }
            }

