            #[derive(Debug)]
            pub(in crate::android_debug_bridge::rustls) struct NewSessionTicketPayloadTls13 {
                pub(in crate::android_debug_bridge::rustls) lifetime: Duration,
                pub(in crate::android_debug_bridge::rustls) age_add: u32,
                pub(in crate::android_debug_bridge::rustls) nonce: SizedPayload<'static, u8>,
                pub(in crate::android_debug_bridge::rustls) ticket:
                    Arc<SizedPayload<'static, u16, MaybeEmpty>>,
                pub(in crate::android_debug_bridge::rustls) extensions: NewSessionTicketExtensions,
            }

            impl NewSessionTicketPayloadTls13 {
                pub(in crate::android_debug_bridge::rustls) fn new(
                    lifetime: Duration,
                    age_add: u32,
                    nonce: [u8; 32],
                    ticket: Vec<u8>,
                ) -> Self {
                    Self {
                        lifetime,
                        age_add,
                        nonce: nonce.to_vec().into(),
                        ticket: Arc::new(SizedPayload::from(Payload::new(ticket))),
                        extensions: NewSessionTicketExtensions::default(),
                    }
                }
            }

            impl Codec<'_> for NewSessionTicketPayloadTls13 {
                fn encode(&self, bytes: &mut Vec<u8>) {
                    (self.lifetime.as_secs() as u32).encode(bytes);
                    self.age_add.encode(bytes);
                    self.nonce.encode(bytes);
                    self.ticket.encode(bytes);
                    self.extensions.encode(bytes);
                }

                fn read(r: &mut Reader<'_>) -> Result<Self, InvalidMessage> {
                    let lifetime = Duration::from_secs(u32::read(r)? as u64);
                    let age_add = u32::read(r)?;
                    let nonce = SizedPayload::read(r)?.into_owned();

                    let ticket = Arc::new(match SizedPayload::<u16, NonEmpty>::read(r) {
                        Err(InvalidMessage::IllegalEmptyList(_)) => {
                            Err(InvalidMessage::EmptyTicketValue)
                        }
                        Err(err) => Err(err),
                        Ok(pl) => Ok(SizedPayload::from(Payload::new(pl.into_vec()))),
                    }?);
                    let extensions = NewSessionTicketExtensions::read(r)?;

                    Ok(Self {
                        lifetime,
                        age_add,
                        nonce,
                        ticket,
                        extensions,
                    })
                }
            }

