            #[derive(Clone, Debug)]
            pub(in crate::android_debug_bridge::rustls) struct ServerHelloPayload {
                pub(in crate::android_debug_bridge::rustls) legacy_version: ProtocolVersion,
                pub(in crate::android_debug_bridge::rustls) random: Random,
                pub(in crate::android_debug_bridge::rustls) session_id: SessionId,
                pub(in crate::android_debug_bridge::rustls) cipher_suite: CipherSuite,
                pub(in crate::android_debug_bridge::rustls) compression_method: Compression,
                pub(in crate::android_debug_bridge::rustls) extensions:
                    Box<ServerExtensions<'static>>,
            }

            impl Codec<'_> for ServerHelloPayload {
                fn encode(&self, bytes: &mut Vec<u8>) {
                    self.payload_encode(bytes, Encoding::Standard)
                }

                fn read(r: &mut Reader<'_>) -> Result<Self, InvalidMessage> {
                    r.all("ServerHelloPayload", |r| {
                        let session_id = SessionId::read(r)?;
                        let suite = CipherSuite::read(r)?;
                        let compression = Compression::read(r)?;

                        let extensions = Box::new(
                            if r.any_left() {
                                ServerExtensions::read(r)?
                            } else {
                                ServerExtensions::default()
                            }
                            .into_owned(),
                        );

                        Ok(Self {
                            legacy_version: ProtocolVersion(0),
                            random: ZERO_RANDOM,
                            session_id,
                            cipher_suite: suite,
                            compression_method: compression,
                            extensions,
                        })
                    })
                }
            }

            impl ServerHelloPayload {
                pub(super) fn payload_encode(&self, bytes: &mut Vec<u8>, encoding: Encoding) {
                    debug_assert!(
                        !matches!(encoding, Encoding::EchConfirmation),
                        "we cannot compute an ECH confirmation on a received ServerHello"
                    );

                    self.legacy_version.encode(bytes);
                    self.random.encode(bytes);
                    self.session_id.encode(bytes);
                    self.cipher_suite.encode(bytes);
                    self.compression_method.encode(bytes);
                    self.extensions.encode(bytes);
                }
            }

            impl Deref for ServerHelloPayload {
                type Target = ServerExtensions<'static>;
                fn deref(&self) -> &Self::Target {
                    &self.extensions
                }
            }

            impl DerefMut for ServerHelloPayload {
                fn deref_mut(&mut self) -> &mut Self::Target {
                    &mut self.extensions
                }
            }

