        pub(in crate::android_debug_bridge::rustls) struct HandshakeFlight<'a, const TLS13: bool> {
            pub(in crate::android_debug_bridge::rustls) transcript: &'a mut HandshakeHash,
            body: Vec<u8>,
        }

        impl<'a, const TLS13: bool> HandshakeFlight<'a, TLS13> {
            pub(in crate::android_debug_bridge::rustls) fn new(
                transcript: &'a mut HandshakeHash,
            ) -> Self {
                Self {
                    transcript,
                    body: Vec::new(),
                }
            }

            pub(in crate::android_debug_bridge::rustls) fn add(
                &mut self,
                hs: HandshakeMessagePayload<'_>,
            ) {
                let start_len = self.body.len();
                hs.encode(&mut self.body);
                self.transcript.add(&self.body[start_len..]);
            }

            pub(in crate::android_debug_bridge::rustls) fn finish(
                self,
                output: &mut dyn Output<'_>,
            ) {
                let m = Message {
                    version: EncodableVersion::Legacy(match TLS13 {
                        true => ProtocolVersion::TLSv1_3,
                        false => ProtocolVersion::TLSv1_2,
                    }),
                    payload: MessagePayload::HandshakeFlight(Payload::new(self.body)),
                };

                output.send_msg(m, TLS13);
            }
        }

