        impl KeyingMaterialExporter {
            pub fn derive<T: AsMut<[u8]>>(
                &self,
                label: &[u8],
                context: Option<&[u8]>,
                mut output: T,
            ) -> Result<T, Error> {
                if output.as_mut().is_empty() {
                    return Err(ApiMisuse::ExporterOutputZeroLength.into());
                }

                self.inner
                    .derive(label, context, output.as_mut())
                    .map(|_| output)
            }
        }

