        pub(in crate::android_debug_bridge::rustls) struct SideCommonOutput<'a, 'q> {
            pub(in crate::android_debug_bridge::rustls) side: &'a mut dyn SideOutput,
            pub(in crate::android_debug_bridge::rustls) quic: Option<&'q mut dyn QuicOutput>,
            pub(in crate::android_debug_bridge::rustls) common: &'a mut CommonState,
            pub(in crate::android_debug_bridge::rustls) tls: &'a mut Vec<u8>,
        }

        impl<'q> Output<'_> for SideCommonOutput<'_, 'q> {
            fn emit(&mut self, ev: Event<'_>) {
                self.side.emit(ev);
            }

            fn output(&mut self, ev: OutputEvent<'_>) {
                if let OutputEvent::ProtocolVersion(ver) = ev {
                    self.common.recv.negotiated_version = Some(ver);
                    self.common.send.negotiated_version(ver);
                }
                self.common.outputs.handle(ev);
            }

            fn send_msg(&mut self, m: Message<'_>, must_encrypt: bool) {
                match self.quic() {
                    Some(quic) => quic.send_msg(m, must_encrypt),
                    None => self.common.send.send_msg(m, must_encrypt, self.tls),
                }
            }

            fn quic(&mut self) -> Option<&mut dyn QuicOutput> {
                match self.quic.as_mut() {
                    Some(q) => Some(&mut **q),
                    None => None,
                }
            }

            fn start_traffic(&mut self) {
                self.common.recv.may_receive_application_data = true;
                self.common.send.start_outgoing_traffic();
            }

            fn receive(&mut self) -> &mut ReceivePath {
                &mut self.common.recv
            }

            fn send(&mut self) -> &mut dyn SendOutput {
                &mut self.common.send
            }
        }

