        pub mod hash {
            use std::boxed::Box;

            use crate::android_debug_bridge::pki_types::FipsStatus;

            use super::enums::HashAlgorithm;

            pub trait Hash: Send + Sync {
                fn start(&self) -> Box<dyn Context>;

                fn hash(&self, data: &[u8]) -> Output;

                fn output_len(&self) -> usize;

                fn algorithm(&self) -> HashAlgorithm;

                fn fips(&self) -> FipsStatus {
                    FipsStatus::Unvalidated
                }
            }

            pub struct Output {
                buf: [u8; Self::MAX_LEN],
                used: usize,
            }

            impl Output {
                pub fn new(bytes: &[u8]) -> Self {
                    let mut output = Self {
                        buf: [0u8; Self::MAX_LEN],
                        used: bytes.len(),
                    };
                    debug_assert!(bytes.len() <= Self::MAX_LEN);
                    output.buf[..bytes.len()].copy_from_slice(bytes);
                    output
                }

                pub const MAX_LEN: usize = 64;
            }

            impl AsRef<[u8]> for Output {
                fn as_ref(&self) -> &[u8] {
                    &self.buf[..self.used]
                }
            }

            pub trait Context: Send + Sync {
                fn fork_finish(&self) -> Output;

                fn fork(&self) -> Box<dyn Context>;

                fn finish(self: Box<Self>) -> Output;

                fn update(&mut self, data: &[u8]);
            }
        }

        pub mod hmac {
            use core::mem;
            use std::boxed::Box;

            use crate::android_debug_bridge::pki_types::FipsStatus;
            use crate::android_debug_bridge::zeroize::Zeroize;

            pub trait Hmac: Send + Sync {
                fn with_key(&self, key: &[u8]) -> Box<dyn Key>;

                fn hash_output_len(&self) -> usize;

                fn fips(&self) -> FipsStatus {
                    FipsStatus::Unvalidated
                }
            }

            #[derive(Clone)]
            pub struct Tag(PublicTag);

            impl Tag {
                pub fn new(bytes: &[u8]) -> Self {
                    Self(PublicTag::new(bytes))
                }

                pub(in crate::android_debug_bridge::rustls) fn into_public(self) -> PublicTag {
                    let public = self.0.clone();
                    mem::forget(self);
                    public
                }

                pub const MAX_LEN: usize = 64;
            }

            impl Drop for Tag {
                #[inline(never)]
                fn drop(&mut self) {
                    self.0.buf[..self.0.used].zeroize();
                }
            }

            impl AsRef<[u8]> for Tag {
                fn as_ref(&self) -> &[u8] {
                    self.0.as_ref()
                }
            }

            #[derive(Clone)]
            pub(in crate::android_debug_bridge::rustls) struct PublicTag {
                buf: [u8; Tag::MAX_LEN],
                used: usize,
            }

            impl PublicTag {
                pub(in crate::android_debug_bridge::rustls) fn new(bytes: &[u8]) -> Self {
                    let mut tag = Self {
                        buf: [0u8; Tag::MAX_LEN],
                        used: bytes.len(),
                    };
                    tag.buf[..bytes.len()].copy_from_slice(bytes);
                    tag
                }
            }

            impl AsRef<[u8]> for PublicTag {
                fn as_ref(&self) -> &[u8] {
                    &self.buf[..self.used]
                }
            }

            pub trait Key: Send + Sync {
                fn sign(&self, data: &[&[u8]]) -> Tag {
                    self.sign_concat(&[], data, &[])
                }

                fn sign_concat(&self, first: &[u8], middle: &[&[u8]], last: &[u8]) -> Tag;

                fn tag_len(&self) -> usize;
            }
        }

