            impl KeyScheduleTraffic {
                pub(in crate::android_debug_bridge::rustls) fn split(
                    self,
                ) -> (KeyScheduleTrafficSend, KeyScheduleTrafficReceive) {
                    let (send, receive) = match self.ks.side {
                        Side::Client => (
                            self.current_client_traffic_secret,
                            self.current_server_traffic_secret,
                        ),
                        Side::Server => (
                            self.current_server_traffic_secret,
                            self.current_client_traffic_secret,
                        ),
                    };

                    (
                        KeyScheduleTrafficSend {
                            ks: self.ks,
                            current: send,
                        },
                        KeyScheduleTrafficReceive {
                            ks: self.ks,
                            current: receive,
                        },
                    )
                }
            }

            pub(in crate::android_debug_bridge::rustls) struct KeyScheduleTrafficSend {
                ks: KeyScheduleSuite,
                current: OkmBlock,
            }

            impl KeyScheduleTrafficSend {
                pub(in crate::android_debug_bridge::rustls) fn update_encrypter_for_key_update(
                    &mut self,
                    send: &mut dyn SendOutput,
                ) {
                    let secret = self.ks.derive_next(&self.current);
                    self.ks.set_encrypter(&secret, send);
                    self.current = secret;
                }

                pub(in crate::android_debug_bridge::rustls) fn update_encrypter(
                    &mut self,
                    send: &mut dyn SendOutput,
                ) {
                    let secret = self.ks.derive_next(&self.current);
                    self.ks.set_encrypter(&secret, send);
                    self.current = secret;
                }

                pub(in crate::android_debug_bridge::rustls) fn refresh_traffic_secret(
                    &mut self,
                ) -> Result<ConnectionTrafficSecrets, Error> {
                    self.current = self.ks.derive_next(&self.current);
                    self.extract()
                }

                pub(in crate::android_debug_bridge::rustls) fn extract(
                    &self,
                ) -> Result<ConnectionTrafficSecrets, Error> {
                    let suite = self.ks.state.suite();
                    let (key, iv) = expand_secret(
                        &self.current,
                        suite.hkdf_provider,
                        suite.aead_alg.key_len(),
                        suite.aead_alg.iv_len(),
                    );

                    Ok(suite.aead_alg.extract_keys(key, iv)?)
                }
            }

