            type AdbEndEntityCert<'a> = crate::android_debug_bridge::webpki::EndEntityCert<'a>;

            pub struct ParsedCertificate<'a>(
                pub(in crate::android_debug_bridge::rustls) AdbEndEntityCert<'a>,
            );

            impl ParsedCertificate<'_> {
                pub fn subject_public_key_info(&self) -> SubjectPublicKeyInfoDer<'static> {
                    self.0.subject_public_key_info()
                }
            }

            impl<'a> TryFrom<&'a CertificateDer<'a>> for ParsedCertificate<'a> {
                type Error = Error;
                fn try_from(value: &'a CertificateDer<'a>) -> Result<Self, Self::Error> {
                    crate::android_debug_bridge::webpki::EndEntityCert::try_from(value)
                        .map_err(pki_error)
                        .map(ParsedCertificate)
                }
            }

            pub fn verify_tls12_signature(
                input: &SignatureVerificationInput<'_>,
                supported_schemes: &WebPkiSupportedAlgorithms,
            ) -> Result<HandshakeSignatureValid, Error> {
                if input.signature.scheme.algorithm().is_none() {
                    return Err(PeerMisbehaved::SignedHandshakeWithUnadvertisedSigScheme.into());
                }

                let possible_algs = supported_schemes.convert_scheme(input.signature.scheme)?;
                let cert = match input.signer {
                    SignerPublicKey::X509(cert_der) => {
                        crate::android_debug_bridge::webpki::EndEntityCert::try_from(*cert_der)
                            .map_err(pki_error)?
                    }
                    SignerPublicKey::RawPublicKey(_) => {
                        return Err(ApiMisuse::InvalidSignerForProtocolVersion.into());
                    }
                };

                let mut error = None;
                for alg in possible_algs {
                    match cert.verify_signature(*alg, input.message, input.signature.signature()) {
            Err(err @ crate::android_debug_bridge::webpki::Error::UnsupportedSignatureAlgorithmForPublicKey(_)) => {
                error = Some(err);
                continue;
            }
            Err(e) => return Err(pki_error(e)),
            Ok(()) => return Ok(HandshakeSignatureValid::assertion()),
        }
                }

                Err(match error {
                    Some(e) => pki_error(e),
                    None => Error::ApiMisuse(ApiMisuse::NoSignatureVerificationAlgorithms),
                })
            }

            pub fn verify_tls13_signature(
                input: &SignatureVerificationInput<'_>,
                supported_schemes: &WebPkiSupportedAlgorithms,
            ) -> Result<HandshakeSignatureValid, Error> {
                if !input.signature.scheme.supported_in_tls13() {
                    return Err(PeerMisbehaved::SignedHandshakeWithUnadvertisedSigScheme.into());
                }

                let &alg = supported_schemes
                    .convert_scheme(input.signature.scheme)?
                    .first()
                    .ok_or(Error::ApiMisuse(
                        ApiMisuse::NoSignatureVerificationAlgorithms,
                    ))?;

                match input.signer {
                    SignerPublicKey::X509(cert_der) => {
                        crate::android_debug_bridge::webpki::EndEntityCert::try_from(*cert_der)
                            .and_then(|cert| {
                                cert.verify_signature(
                                    alg,
                                    input.message,
                                    input.signature.signature(),
                                )
                            })
                    }
                    SignerPublicKey::RawPublicKey(spki) => {
                        crate::android_debug_bridge::webpki::RawPublicKeyEntity::try_from(*spki)
                            .and_then(|rpk| {
                                rpk.verify_signature(
                                    alg,
                                    input.message,
                                    input.signature.signature(),
                                )
                            })
                    }
                }
                .map_err(pki_error)
                .map(|_| HandshakeSignatureValid::assertion())
            }

            pub(in crate::android_debug_bridge::rustls) fn verify_identity_signed_by_trust_anchor_impl(
                cert: &ParsedCertificate<'_>,
                roots: &RootCertStore,
                intermediates: &[CertificateDer<'_>],
                revocation: Option<crate::android_debug_bridge::webpki::RevocationOptions<'_>>,
                now: UnixTime,
                supported_algs: &[&dyn SignatureVerificationAlgorithm],
            ) -> Result<(), Error> {
                let result = cert.0.verify_for_usage(
                    supported_algs,
                    &roots.roots,
                    intermediates,
                    now,
                    &ExtendedKeyUsage::server_auth(),
                    revocation,
                    None,
                );
                match result {
                    Ok(_) => Ok(()),
                    Err(e) => Err(pki_error(e)),
                }
            }

