            #[non_exhaustive]
            #[derive(Debug)]
            pub enum ServerHandshake {
                NeedsInput(NeedsInput<ServerSide>),

                Accepted(Accepted),

                VerifyClientIdentity(VerifyPeerIdentity<ServerSide>),

                Complete(SplitConnection<ServerSide>),
            }

            impl ServerHandshake {
                pub fn start() -> NeedsInput<ServerSide> {
                    NeedsInput {
                        inner: ConnectionCommon::for_acceptor(Protocol::Tcp),
                    }
                }
            }

            impl TryFrom<ConnectionCommon<ServerSide>> for ServerHandshake {
                type Error = Error;

                fn try_from(mut inner: ConnectionCommon<ServerSide>) -> Result<Self, Error> {
                    const MISUSED: Error = Error::Unreachable("forgot to restore state");

                    Ok(match mem::replace(&mut inner.state, Err(MISUSED))? {
                        ServerState::ChooseConfig(choose_config) => Self::Accepted(Accepted {
                            inner,
                            choose_config,
                        }),

                        ServerState::VerifyClientIdentity(verify_identity) => {
                            Self::VerifyClientIdentity(VerifyPeerIdentity {
                                inner,
                                verify_identity,
                            })
                        }

                        state if state.is_traffic() => {
                            inner.state = Ok(state);
                            Self::Complete(SplitConnection::try_from(inner)?)
                        }

                        state => {
                            inner.state = Ok(state);
                            Self::NeedsInput(NeedsInput { inner })
                        }
                    })
                }
            }

            pub struct Accepted {
                inner: ConnectionCommon<ServerSide>,
                choose_config: Box<ChooseConfig>,
            }

            impl Accepted {
                pub fn client_hello(&self) -> ClientHello<'_> {
                    let ch = self.choose_config.client_hello();
                    trace!("Accepted::client_hello(): {ch:#?}");
                    ch
                }

                pub fn choose_config(
                    mut self,
                    config: Arc<ServerConfig>,
                    tls: &mut Vec<u8>,
                ) -> Result<ServerHandshake, Error> {
                    let result = self.inner.accepted(
                        self.choose_config,
                        ServerExtensionsInput::default(),
                        None,
                        config,
                        tls,
                    );

                    let send_path = &mut self.inner.common.send;

                    if let Err(err) = &result {
                        maybe_send_fatal_alert(send_path, err, tls);
                    }

                    result?;

                    Ok(ServerHandshake::NeedsInput(NeedsInput {
                        inner: self.inner,
                    }))
                }
            }

            impl fmt::Debug for Accepted {
                fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
                    f.debug_struct("Accepted").finish_non_exhaustive()
                }
            }

            pub struct ReadEarlyData<'a> {
                common: &'a mut ConnectionCommon<ServerSide>,
            }

            impl<'a> ReadEarlyData<'a> {
                fn new(common: &'a mut ConnectionCommon<ServerSide>) -> Self {
                    ReadEarlyData { common }
                }

                pub fn exporter(&mut self) -> Result<KeyingMaterialExporter, Error> {
                    self.common.common.early_exporter()
                }
            }

            impl io::Read for ReadEarlyData<'_> {
                fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
                    self.common.side.early_data.read(buf)
                }
            }

            #[derive(Default)]
            pub(super) enum EarlyDataState {
                #[default]
                New,
                Accepted {
                    received: ChunkVecBuffer,
                },
            }

            impl EarlyDataState {
                fn accept(&mut self) {
                    *self = Self::Accepted {
                        received: ChunkVecBuffer::new(),
                    };
                }

                fn was_accepted(&self) -> bool {
                    matches!(self, Self::Accepted { .. })
                }

                #[allow(dead_code)]
                fn peek(&self) -> Option<&[u8]> {
                    match self {
                        Self::Accepted { received, .. } => received.peek(),
                        _ => None,
                    }
                }

                #[allow(dead_code)]
                fn pop(&mut self) -> Option<Vec<u8>> {
                    match self {
                        Self::Accepted { received, .. } => received.pop(),
                        _ => None,
                    }
                }

                fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
                    match self {
                        Self::Accepted { received, .. } => Ok(received.read(buf)),
                        _ => Err(io::Error::from(io::ErrorKind::BrokenPipe)),
                    }
                }

                fn take_received_plaintext(&mut self, bytes: Payload<'_>) {
                    let Self::Accepted { received } = self else {
                        return;
                    };

                    received.append(bytes.into_vec());
                }
            }

            impl ConnectionCommon<ServerSide> {
                pub(in crate::android_debug_bridge::rustls) fn for_server(
                    config: Arc<ServerConfig>,
                    extra_exts: ServerExtensionsInput,
                    protocol: Protocol,
                ) -> Result<Self, Error> {
                    let mut common = CommonState::new(Side::Server, config.fips());
                    common
                        .send
                        .set_max_fragment_size(config.max_fragment_size)?;
                    Ok(Self::new(
                        Box::new(ExpectClientHello::new(
                            config,
                            extra_exts,
                            Vec::new(),
                            protocol,
                        ))
                        .into(),
                        ServerConnectionData::default(),
                        common,
                    ))
                }

                pub(in crate::android_debug_bridge::rustls) fn for_acceptor(
                    protocol: Protocol,
                ) -> Self {
                    Self::new(
                        ReadClientHello::new(protocol).into(),
                        ServerConnectionData::default(),
                        CommonState::new(Side::Server, FipsStatus::Unvalidated),
                    )
                }
            }

            #[derive(Default)]
            pub(in crate::android_debug_bridge::rustls) struct ServerConnectionData {
                sni: Option<DnsName<'static>>,
                received_resumption_data: Option<Vec<u8>>,
                early_data: EarlyDataState,
            }

