    #[cfg(all())]
    pub(in crate::android_debug_bridge::provider) mod ticketer {
        use core::fmt;
        use core::fmt::{Debug, Formatter};
        use core::sync::atomic::{AtomicUsize, Ordering};
        use core::time::Duration;
        use std::boxed::Box;
        use std::vec::Vec;

        use crate::android_debug_bridge::graviola::ring::aead;
        use crate::android_debug_bridge::graviola::ring::rand::{SecureRandom, SystemRandom};
        use crate::android_debug_bridge::rustls::crypto::TicketProducer;
        use crate::android_debug_bridge::rustls::error::Error;
        use crate::android_debug_bridge::subtle::ConstantTimeEq;

        pub(super) struct AeadTicketer {
            alg: &'static aead::Algorithm,
            key: aead::LessSafeKey,
            key_name: [u8; 16],

            maximum_ciphertext_len: AtomicUsize,
        }

        impl AeadTicketer {
            #[allow(clippy::new_ret_no_self)]
            pub(super) fn new() -> Result<Box<dyn TicketProducer>, Error> {
                let mut key = [0u8; 32];
                SystemRandom::new()
                    .fill(&mut key)
                    .map_err(|_| Error::FailedToGetRandomBytes)?;

                let key = aead::UnboundKey::new(TICKETER_AEAD, &key).unwrap();

                let mut key_name = [0u8; 16];
                SystemRandom::new()
                    .fill(&mut key_name)
                    .map_err(|_| Error::FailedToGetRandomBytes)?;

                Ok(Box::new(Self {
                    alg: TICKETER_AEAD,
                    key: aead::LessSafeKey::new(key),
                    key_name,
                    maximum_ciphertext_len: AtomicUsize::new(0),
                }))
            }
        }

        impl TicketProducer for AeadTicketer {
            fn encrypt(&self, message: &[u8]) -> Option<Vec<u8>> {
                let mut nonce_buf = [0u8; 12];
                SystemRandom::new().fill(&mut nonce_buf).ok()?;
                let nonce = aead::Nonce::assume_unique_for_key(nonce_buf);
                let aad = aead::Aad::from(self.key_name);

                let mut ciphertext = Vec::with_capacity(
                    self.key_name.len()
                        + nonce_buf.len()
                        + message.len()
                        + self.key.algorithm().tag_len(),
                );
                ciphertext.extend(self.key_name);
                ciphertext.extend(nonce_buf);
                ciphertext.extend(message);
                match self.key.seal_in_place_separate_tag(
                    nonce,
                    aad,
                    &mut ciphertext[self.key_name.len() + nonce_buf.len()..],
                ) {
                    Ok(tag) => ciphertext.extend(tag.as_ref()),
                    Err(_) => return None,
                }

                self.maximum_ciphertext_len
                    .fetch_max(ciphertext.len(), Ordering::SeqCst);
                Some(ciphertext)
            }

            fn decrypt(&self, ciphertext: &[u8]) -> Option<Vec<u8>> {
                if ciphertext.len() > self.maximum_ciphertext_len.load(Ordering::SeqCst) {
                    return None;
                }

                let (alleged_key_name, ciphertext) =
                    ciphertext.split_at_checked(self.key_name.len())?;

                let (nonce, ciphertext) = ciphertext.split_at_checked(self.alg.nonce_len())?;

                if ConstantTimeEq::ct_ne(&self.key_name[..], alleged_key_name).into() {
                    return None;
                }

                let nonce = aead::Nonce::try_assume_unique_for_key(nonce).ok()?;

                let mut out = Vec::from(ciphertext);

                let plain_len = self
                    .key
                    .open_in_place(nonce, aead::Aad::from(alleged_key_name), &mut out)
                    .ok()?
                    .len();
                out.truncate(plain_len);

                Some(out)
            }

            fn lifetime(&self) -> Duration {
                Duration::ZERO
            }
        }

        impl Debug for AeadTicketer {
            fn fmt(&self, f: &mut Formatter<'_>) -> fmt::Result {
                f.debug_struct("AeadTicketer")
                    .field("alg", &self.alg)
                    .finish_non_exhaustive()
            }
        }

        static TICKETER_AEAD: &aead::Algorithm = &aead::CHACHA20_POLY1305;

        #[cfg(all(test, all()))]
        crate::adb_t051!($);
    }
