pub mod rustls_util {
    use std::io;

    use crate::android_debug_bridge::rustls::{Connection, VecInput};

    mod key_log_file {
        use core::fmt::{Debug, Formatter};
        use std::env::var_os;
        use std::ffi::OsString;
        use std::fs::{File, OpenOptions};
        use std::io;
        use std::io::Write;
        #[cfg(unix)]
        use std::os::unix::fs::OpenOptionsExt;
        use std::sync::Mutex;

        use crate::android_debug_bridge::rustls::KeyLog;
        #[cfg(all())]
        use crate::android_debug_bridge::tracing::warn;

        struct KeyLogFileInner {
            file: Option<File>,
            buf: Vec<u8>,
        }

        impl KeyLogFileInner {
            fn new(var: Option<OsString>) -> Self {
                let Some(path) = &var else {
                    return Self {
                        file: None,
                        buf: Vec::new(),
                    };
                };

                let mut options = OpenOptions::new();
                options.append(true).create(true);

                #[cfg(unix)]
                options.mode(0o600);

                #[cfg_attr(not(all()), allow(clippy::manual_ok_err))]
                let file = match options.open(path) {
                    Ok(f) => Some(f),
                    #[cfg_attr(not(all()), allow(unused_variables))]
                    Err(e) => {
                        #[cfg(all())]
                        warn!("unable to create key log file {path:?}: {e}");
                        None
                    }
                };

                Self {
                    file,
                    buf: Vec::new(),
                }
            }

            fn try_write(
                &mut self,
                label: &str,
                client_random: &[u8],
                secret: &[u8],
            ) -> io::Result<()> {
                let Some(file) = &mut self.file else {
                    return Ok(());
                };

                self.buf.clear();
                write!(self.buf, "{label} ")?;
                for b in client_random.iter() {
                    write!(self.buf, "{b:02x}")?;
                }
                write!(self.buf, " ")?;
                for b in secret.iter() {
                    write!(self.buf, "{b:02x}")?;
                }
                writeln!(self.buf)?;
                file.write_all(&self.buf)
            }
        }

        impl Debug for KeyLogFileInner {
            fn fmt(&self, f: &mut Formatter<'_>) -> core::fmt::Result {
                f.debug_struct("KeyLogFileInner")
                    .field("file", &self.file)
                    .finish_non_exhaustive()
            }
        }

        pub struct KeyLogFile(Mutex<KeyLogFileInner>);

        impl KeyLogFile {
            pub fn new() -> Self {
                let var = var_os("SSLKEYLOGFILE");
                Self(Mutex::new(KeyLogFileInner::new(var)))
            }
        }

        impl KeyLog for KeyLogFile {
            fn log(&self, label: &str, client_random: &[u8], secret: &[u8]) {
                match self
                    .0
                    .lock()
                    .unwrap()
                    .try_write(label, client_random, secret)
                {
                    Ok(()) => {}
                    #[cfg_attr(not(all()), allow(unused_variables))]
                    Err(e) => {
                        #[cfg(all())]
                        warn!("error writing to key log file: {e}");
                    }
                }
            }
        }

        impl Debug for KeyLogFile {
            fn fmt(&self, f: &mut Formatter<'_>) -> core::fmt::Result {
                match self.0.try_lock() {
                    Ok(key_log_file) => write!(f, "{key_log_file:?}"),
                    Err(_) => write!(f, "KeyLogFile {{ <locked> }}"),
                }
            }
        }

        #[cfg(all(test, any(target_os = "linux", target_os = "macos")))]
        crate::adb_t055!($);
    }
    pub use key_log_file::KeyLogFile;

    mod stream {

        use std::io::{BufRead, Error, ErrorKind, IoSlice, Read, Result, Write};

        use crate::android_debug_bridge::rustls::crypto::cipher::OutboundPlain;
        use crate::android_debug_bridge::rustls::{Connection, TlsInputBuffer, VecInput};

        use crate::android_debug_bridge::rustls_util::complete_io;

        #[allow(clippy::exhaustive_structs)]
        #[derive(Debug)]
        pub struct Stream<'a, C: 'a + ?Sized, T: 'a + Read + Write + ?Sized> {
            pub conn: &'a mut C,

            pub sock: &'a mut T,

            pub input: &'a mut VecInput,

            pub received_plaintext: &'a mut Vec<u8>,

            pub output: &'a mut Vec<u8>,

            pub limit: usize,
        }

        impl<'a, C, T> Stream<'a, C, T>
        where
            C: 'a + Connection,
            T: 'a + Read + Write,
        {
            pub fn new(
                input: &'a mut VecInput,
                received_plaintext: &'a mut Vec<u8>,
                output: &'a mut Vec<u8>,
                conn: &'a mut C,
                sock: &'a mut T,
            ) -> Self {
                Self {
                    conn,
                    sock,
                    input,
                    received_plaintext,
                    output,
                    limit: DEFAULT_BUFFER_LIMIT,
                }
            }

            fn complete_prior_io(&mut self) -> Result<()> {
                if self.conn.is_handshaking() {
                    complete_io(
                        self.sock,
                        self.input,
                        self.received_plaintext,
                        self.output,
                        self.conn,
                    )?;
                }

                if !self.output.is_empty() {
                    complete_io(
                        self.sock,
                        self.input,
                        self.received_plaintext,
                        self.output,
                        self.conn,
                    )?;
                }

                Ok(())
            }

            fn prepare_read(&mut self) -> Result<()> {
                self.complete_prior_io()?;

                while self.received_plaintext.is_empty() && self.conn.wants_read() {
                    if complete_io(
                        self.sock,
                        self.input,
                        self.received_plaintext,
                        self.output,
                        self.conn,
                    )?
                    .0 == 0
                    {
                        break;
                    }
                }

                if self.received_plaintext.is_empty() && self.input.has_seen_eof() {
                    return Err(Error::new(
                        ErrorKind::UnexpectedEof,
                        "peer closed connection without sending TLS close_notify",
                    ));
                }

                Ok(())
            }
        }

        impl<'a, C, T> Read for Stream<'a, C, T>
        where
            C: 'a + Connection,
            T: 'a + Read + Write,
        {
            fn read(&mut self, buf: &mut [u8]) -> Result<usize> {
                self.prepare_read()?;
                let len = Ord::min(buf.len(), self.received_plaintext.len());
                let Some((src, _)) = self.received_plaintext.split_at_checked(len) else {
                    return Ok(0);
                };

                let Some((dst, _)) = buf.split_at_mut_checked(len) else {
                    return Ok(0);
                };

                dst.copy_from_slice(src);
                self.received_plaintext.drain(..len);
                Ok(len)
            }
        }

        impl<'a, C, T> BufRead for Stream<'a, C, T>
        where
            C: 'a + Connection,
            T: 'a + Read + Write,
        {
            fn fill_buf(&mut self) -> Result<&[u8]> {
                self.prepare_read()?;
                Ok(self.received_plaintext)
            }

            fn consume(&mut self, amt: usize) {
                self.received_plaintext.drain(..amt);
            }
        }

        impl<'a, C, T> Write for Stream<'a, C, T>
        where
            C: 'a + Connection,
            T: 'a + Read + Write,
        {
            fn write(&mut self, buf: &[u8]) -> Result<usize> {
                self.complete_prior_io()?;
                if self.conn.is_handshaking() {
                    return Err(ErrorKind::WouldBlock.into());
                }

                let len = Ord::min(buf.len(), self.limit.saturating_sub(self.output.len()));
                if len == 0 && !buf.is_empty() {
                    return Err(ErrorKind::WouldBlock.into());
                }

                self.conn
                    .write((&buf[..len]).into(), self.output)
                    .map_err(|err| Error::new(ErrorKind::InvalidData, err))?;

                let _ = complete_io(
                    self.sock,
                    self.input,
                    self.received_plaintext,
                    self.output,
                    self.conn,
                );

                Ok(len)
            }

            fn write_vectored(&mut self, bufs: &[IoSlice<'_>]) -> Result<usize> {
                self.complete_prior_io()?;
                if self.conn.is_handshaking() {
                    return Err(ErrorKind::WouldBlock.into());
                }

                let mut available = self.limit.saturating_sub(self.output.len());
                let mut len = 0;
                let mut slices = Vec::with_capacity(bufs.len());
                for buf in bufs {
                    let take = Ord::min(buf.len(), available);
                    slices.push(&buf[..take]);
                    len += take;
                    available -= take;
                }

                if len == 0 && bufs.iter().any(|buf| !buf.is_empty()) {
                    return Err(ErrorKind::WouldBlock.into());
                }

                self.conn
                    .write(OutboundPlain::new(&slices), self.output)
                    .map_err(|err| Error::new(ErrorKind::InvalidData, err))?;

                let _ = complete_io(
                    self.sock,
                    self.input,
                    self.received_plaintext,
                    self.output,
                    self.conn,
                );

                Ok(len)
            }

            fn flush(&mut self) -> Result<()> {
                self.complete_prior_io()
            }
        }

        #[allow(clippy::exhaustive_structs)]
        #[derive(Debug)]
        pub struct StreamOwned<C: Sized, T: Read + Write + Sized> {
            pub conn: C,

            pub sock: T,

            pub input: VecInput,

            pub received_plaintext: Vec<u8>,

            pub output: Vec<u8>,

            pub limit: usize,
        }

        impl<C, T> StreamOwned<C, T>
        where
            C: Connection,
            T: Read + Write,
        {
            pub fn new(conn: C, sock: T, output: Vec<u8>) -> Self {
                Self {
                    conn,
                    sock,
                    input: VecInput::default(),
                    received_plaintext: Vec::new(),
                    output,
                    limit: DEFAULT_BUFFER_LIMIT,
                }
            }

            pub fn get_ref(&self) -> &T {
                &self.sock
            }

            pub fn get_mut(&mut self) -> &mut T {
                &mut self.sock
            }

            pub fn into_parts(self) -> (C, T) {
                (self.conn, self.sock)
            }
        }

        impl<'a, C, T> StreamOwned<C, T>
        where
            C: Connection,
            T: Read + Write,
        {
            fn as_stream(&'a mut self) -> Stream<'a, C, T> {
                Stream {
                    conn: &mut self.conn,
                    sock: &mut self.sock,
                    input: &mut self.input,
                    received_plaintext: &mut self.received_plaintext,
                    output: &mut self.output,
                    limit: self.limit,
                }
            }
        }

        impl<C, T> Read for StreamOwned<C, T>
        where
            C: Connection,
            T: Read + Write,
        {
            fn read(&mut self, buf: &mut [u8]) -> Result<usize> {
                self.as_stream().read(buf)
            }
        }

        impl<C, T> BufRead for StreamOwned<C, T>
        where
            C: Connection,
            T: Read + Write,
        {
            fn fill_buf(&mut self) -> Result<&[u8]> {
                self.as_stream().prepare_read()?;
                Ok(&self.received_plaintext)
            }

            fn consume(&mut self, amt: usize) {
                self.as_stream().consume(amt)
            }
        }

        impl<C, T> Write for StreamOwned<C, T>
        where
            C: Connection,
            T: Read + Write,
        {
            fn write(&mut self, buf: &[u8]) -> Result<usize> {
                self.as_stream().write(buf)
            }

            fn flush(&mut self) -> Result<()> {
                self.as_stream().flush()
            }
        }

        const DEFAULT_BUFFER_LIMIT: usize = 64 * 1024;

        #[cfg(test)]
        crate::adb_t056!($);
    }
    pub use crate::android_debug_bridge::rustls_util::stream::{Stream, StreamOwned};

    pub fn complete_io(
        io: &mut (impl io::Read + io::Write),
        input: &mut VecInput,
        received_plaintext: &mut Vec<u8>,
        output: &mut Vec<u8>,
        conn: &mut impl Connection,
    ) -> Result<(usize, usize), io::Error> {
        let mut eof = false;
        let mut wrlen = 0;
        let mut rdlen = 0;
        loop {
            let (mut blocked_write, mut blocked_read) = (None, None);
            let until_handshaked = conn.is_handshaking();

            if output.is_empty() && !conn.wants_read() {
                return Ok((rdlen, wrlen));
            }

            let mut sent = 0;
            while sent < output.len() {
                match io.write(&output[sent..]) {
                    Ok(0) => {
                        output.drain(..sent);
                        io.flush()?;
                        return Ok((rdlen, wrlen));
                    }
                    Ok(n) if n > output.len() - sent => {
                        let available = output.len() - sent;
                        output.clear();
                        return Err(io::Error::other(format!(
                            "illegal write() return value ({n} > {available})"
                        )));
                    }
                    Ok(n) => {
                        wrlen += n;
                        sent += n;
                    }
                    Err(err) if err.kind() == io::ErrorKind::WouldBlock => {
                        blocked_write = Some(err);
                        break;
                    }
                    Err(err) => {
                        output.drain(..sent);
                        return Err(err);
                    }
                }
            }
            output.drain(..sent);
            if wrlen > 0 {
                io.flush()?;
            }

            if !until_handshaked && wrlen > 0 {
                return Ok((rdlen, wrlen));
            }

            if let (Some(_), false) = (&blocked_write, conn.wants_read()) {
                return match wrlen {
                    0 => Err(blocked_write.unwrap()),
                    _ => Ok((rdlen, wrlen)),
                };
            }

            while !eof && conn.wants_read() {
                let read_size = match input.read(io) {
                    Ok(0) => {
                        eof = true;
                        Some(0)
                    }
                    Ok(n) => {
                        rdlen += n;
                        Some(n)
                    }
                    Err(err) if err.kind() == io::ErrorKind::WouldBlock => {
                        blocked_read = Some(err);
                        break;
                    }
                    Err(err) if err.kind() == io::ErrorKind::Interrupted => None,
                    Err(err) => return Err(err),
                };
                if read_size.is_some() {
                    break;
                }
            }

            let error = conn
                .read_tls(input, output)
                .handle_all(received_plaintext)
                .err();

            if let Some(e) = error {
                let _ignored = write_and_drain(io, output);
                let _ignored = io.flush();
                return Err(io::Error::new(io::ErrorKind::InvalidData, e));
            };

            if let Some(error) = blocked_read.take_if(|_| output.is_empty()) {
                return match rdlen {
                    0 => Err(error),
                    _ => Ok((rdlen, wrlen)),
                };
            }

            if until_handshaked && !conn.is_handshaking() && !output.is_empty() {
                continue;
            }

            let blocked = blocked_write.zip(blocked_read);
            match (eof, until_handshaked, conn.is_handshaking(), blocked) {
                (_, true, false, _) => return Ok((rdlen, wrlen)),
                (_, _, _, Some((e, _))) if rdlen == 0 && wrlen == 0 => return Err(e),
                (_, _, _, Some(_)) => return Ok((rdlen, wrlen)),
                (_, false, _, _) => return Ok((rdlen, wrlen)),
                (true, true, true, _) => return Err(io::Error::from(io::ErrorKind::UnexpectedEof)),
                _ => {}
            }
        }
    }

    fn write_and_drain(io: &mut dyn io::Write, output: &mut Vec<u8>) -> io::Result<usize> {
        let n = io.write(output)?;
        if n > output.len() {
            let available = output.len();
            output.clear();
            return Err(io::Error::other(format!(
                "illegal write() return value ({n} > {available})"
            )));
        }
        output.drain(..n);
        Ok(n)
    }
}
